INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-04', '사도행전', '5장 31절 ~ 42절', '예수는 그리스도', '(사도행전 5장)
31 이스라엘에게 회개함과 죄 사함을 주시려고 그를 오른손으로 높이사 임금과 구주로 삼으셨느니라
32 우리는 이 일에 증인이요 하나님이 자기에게 순종하는 사람들에게 주신 성령도 그러하니라 하더라
33 그들이 듣고 크게 노하여 사도들을 없이하고자 할새
34 바리새인 가말리엘은 율법교사로 모든 백성에게 존경을 받는 자라 공회 중에 일어나 명하여 사도들을 잠깐 밖에 나가게 하고
35 말하되 이스라엘 사람들아 너희가 이 사람들에게 대하여 어떻게 하려는지 조심하라
36 이 전에 드다가 일어나 스스로 선전하매 사람이 약 사백 명이나 따르더니 그가 죽임을 당하매 따르던 모든 사람들이 흩어져 없어졌고
37 그 후 호적할 때에 갈릴리의 유다가 일어나 백성을 꾀어 따르게 하다가 그도 망한즉 따르던 모든 사람들이 흩어졌느니라
38 이제 내가 너희에게 말하노니 이 사람들을 상관하지 말고 버려 두라 이 사상과 이 소행이 사람으로부터 났으면 무너질 것이요
39 만일 하나님께로부터 났으면 너희가 그들을 무너뜨릴 수 없겠고 도리어 하나님을 대적하는 자가 될까 하노라 하니
40 그들이 옳게 여겨 사도들을 불러들여 채찍질하며 예수의 이름으로 말하는 것을 금하고 놓으니
41 사도들은 그 이름을 위하여 능욕 받는 일에 합당한 자로 여기심을 기뻐하면서 공회 앞을 떠나니라
42 그들이 날마다 성전에 있든지 집에 있든지 예수는 그리스도라고 가르치기와 전도하기를 그치지 아니하니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 6월19일 사도행전 5장 31절~42절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
이스라엘: 31절, 35절
하나님: 32절, 39절(2)
사도: 33절, 34절, 40절, 41절
공회: 34절, 41절
사람: 35절(2), 36절(2), 37절, 38절(2)
예수: 40절, 42절

4.주제만들기 : 예수는 그리스도
5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 예수는 그리스도라고 외치는 사도들
- 사도의 설교를 듣고 노하는 공회 위원들
- 예수가 사망했음에도 제자들이 떠나지 않고 따르는 것에는 이유가 있을 것이며 그것이 하나님의 뜻이라면 우리가 하나님을 대적하는 것이라고 지혜롭게 말하는 가말리엘
- 사도들을 불러들여 채찍질하며 예수의 이름으로 말하는 것을 금하고 놓는 공회 위원들
- 채찍질 당했음에도 예수님의 이름을 위하여 능욕 받는 일에 합당한 자로 여기심을 기뻐하며 떠나는 사도들
- 날마다 성전에 있든지 집에 있든지 예수는 그리스도라고 가르치기와 전도하기를 그치지 아니하는 사도들

7.하나님 찾기 (해석) 
- 순종하는 자들에게 임하시는 성령님

8.인간(해석): 
- 사도의 설교를 듣고 노하는 공회 위원들 71명 중 아마도 아리마대 요셉과 가말리엘은 노하지 않았을 것이다. 노하는 69명 중 회심 전의 사도 바울도 포함되어 있었을 것이다.
- 베드로는 생명의 말씀을 선포했으나 권력에 취한 공회 위원들과 원로들은 복음으로 받아들이지 않음. 그들에게는 그동안의 삶이 부정당하는 말이라서 기분이 나쁘고 자기들에게 권력과 인기에서 손해가 되는 소리일 뿐임.
- 하나님 중심으로 지혜롭게 상황을 해석하며 앞으로 어떻게 되는지 지켜보자고 당당하게 말하는 가말리엘은 통찰력이 있는 인물이 분명하거나 어쩌면 성령님께서 사도들을 구하고자 역사하셨는지도 모르겠음.
- 채찍에 맞고 능욕 받았음에도 그리고 앞으로도 능욕 받을 것임에도, 예수의 이름으로 예수님의 고난에 동참하는 것을 큰 상으로 여기고 기뻐하는 사도들
- 성령에 취하여 날마다 예수는 그리스도라고 가르치며 전도하는 사도들

9. 적용(나): 
- 날마다 성령 충만해야 한다. 성령에 취한 삶을 살아야 한다.
- 32절을 보면 하나님은 말씀에 순종하는 자에게 성령을 주신다. 나는 반드시 주님의 말씀과 주신 마음에 순종해야 한다.
- 채찍에 맞고 능욕을 받음에도 예수를 전하는 것을 즐거워 한 사도들을 본 받아야 한다.
- 회심 후 예수님을 전하고 싶어서 가슴이 터질 것 같을 때가 있었다. 지금도 그래야 하는데 많이 무뎌졌다. 소극적 전도로 10년 째 사용하고 있는 카톡 인사말 ‘예수는 그리스도’. 이제 다시 뛰는 가슴으로 예수님을 전하며 살아야 겠다.

10. 영적터치(단어/구절) 
42절 예수는 그리스도라고 가르치기와 전하기를 멈추지 아니하였더라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-05', '사도행전', '6장 1절 ~ 10절', '제목 없음', '[행6:1-10]

1 그 때에 제자가 더 많아졌는데 헬라파 유대인들이 자기의 과부들이 매일의 구제에 빠지므로 히브리파 사람을 원망하니

2 열두 사도가 모든 제자를 불러 이르되 우리가 하나님의 말씀을 제쳐 놓고 접대를 일삼는 것이 마땅하지 아니하니

3 형제들아 너희 가운데서 성령과 지혜가 충만하여 칭찬 받는 사람 일곱을 택하라 우리가 이 일을 그들에게 맡기고

4 우리는 오로지 기도하는 일과 말씀 사역에 힘쓰리라 하니

5 온 무리가 이 말을 기뻐하여 믿음과 성령이 충만한 사람 스데반과 또 빌립과 브로고로와 니가노르와 디몬과 바메나와 유대교에 입교했던 안디옥 사람 니골라를 택하여

6 사도들 앞에 세우니 사도들이 기도하고 그들에게 안수하니라

7 하나님의 말씀이 점점 왕성하여 예루살렘에 있는 제자의 수가 더 심히 많아지고 허다한 제사장의 무리도 이 도에 복종하니라

8 스데반이 은혜와 권능이 충만하여 큰 기사와 표적을 민간에 행하니

9 이른 바 자유민들 즉 구레네인, 알렉산드리아인, 길리기아와 아시아에서 온 사람들의 회당에서 어떤 자들이 일어나 스데반과 더불어 논쟁할새

10 스데반이 지혜와 성령으로 말함을 그들이 능히 당하지 못하여

 

3331 생명의 큐티

3:하나님, 인간, 나

3:관찰, 해석, 적용

3:반복단어찾기, 질문하기, 대상이되어봄(본문) 

1:감동받는 단어나 구절 찾기(영적터치)

 

2023년 6월20일 사도행전 6장 1절~10절

1.1분기도

2.본문성경 읽기(3번)

3.반복단어 찾기(형광펜 추천)


	(3,5,10절), 지혜(3,10절), 충만하다(3,5,8절), 제자(1,2절), 사도(6절), 제자의 수가 많아지다(1,7절), 


4.주제만들기 : 성령과 지혜가 충만한 일곱 집사

5.하나님 찾기 (관찰)

-성령이 사도와 제자들에게 임하심

-하나님의 말씀이 왕성해짐

6.인간 찾기 (관찰)

-제자가 많아지고 심히 많아짐

-헬라파 유대인들이 급식 구제 하는 일에 대해 히브리파 사람들에게 불만이 생김

-사도들은 성령과 지혜가 충만한 일곱 사람을 택해 안수함

-스데반이 은혜와 권능이 충만해 큰 기사와 표적을 행함

-자유민들이 스데반과 논쟁하나 지혜와 성령으로 말하여 당하지 못함

 

7.하나님 찾기 (해석) 

-성령으로 임하신 하나님은 말씀으로 왕성히 운행하심

8.인간(해석):

-제자가 많아지자 다툼이 일어났고 다툼을 지혜롭게 해결하고자 성령과 지혜가 충만하여 칭찬 받는 사람 일곱을 세움. 

-사도들은 오직 기도하는 일과 말씀 사역에 힘쓰길 소망함. 예수님의 때를 생각하며 집중했기 때문에 하루를 소중히 여겼을거라 생각됨.

-제자의 수가 심히 많아졌는데 하나님의 말씀이 사도와 제자들을 통해 왕성해지자 제사장의 무리도 복음을 받아들이기 시작함.

-스데반과 같이 성령과 은혜와 권능, 지혜가 충만하면 복음을 전할 때 받는 조롱과 핍박을 이겨냄

9. 적용(나): 

-당시 사도들과 제자들은 예수님의 때를 생각하며 살았다. 예수님의 때가 올 것이란 강력한 소망은 사도와 제자들에게 성령과 지혜가 충만케 했고 복음을 전하는 일에 더욱 힘쓸 수 있는 원동력이 되었다. 지금 우리는 어떤 하루를 살고 있을까? 급격히 변하는 4차산업 시대에 물질의 풍요와 지식, 정보의 대중화로 인해 우리는 부족함 없이 하루를 살고 있다. 풍요롭고 자유롭고 편안한 시대에 살면서 예수님의 때는 생각지 않고 살고 있다. 

-성령과 지혜가 있더라도 충만하지 않다면 즉, 말씀과 기도, 예배, 전도 등 하나님과의 교제에 충만하지 않다면 성령의 역사는 일어나지 않는다. 사도들이 기도와 말씀 사역에 힘쓴 것처럼 본질에 집중하고 힘써야 성령과 지혜와 은혜와 권능이 충만할 수있다. 그 어떠한 것에도 힘쓰지 않는 내 모습을 회개한다. 

-성령이 충만한 것도 중요하지만 지혜와 은혜와 권능이 충만해야 복음을 전할 때 복음에 대항하는 일들을 이겨낼 수 있다. 마포대교와 한강대교, 영동대교를 넘어 세계 곳곳에 아픔이 있는 곳에 복음이 전해질 때 넘어지지 않도록 위의 묵상들을 잘 지키길 원한다.

10. 영적터치(단어/구절) 충만, 왕성

11. 믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-06', '사도행전', '6장 11절 ~ 15절', '거짓 증인들 앞에서 승리하는 스데반', '[행6:11-15]
11 사람들을 매수하여 말하게 하되 이 사람이 모세와 하나님을 모독하는 말을 하는 것을 우리가 들었노라 하게 하고
12 백성과 장로와 서기관들을 충동시켜 와서 잡아가지고 공회에 이르러
13 거짓 증인들을 세우니 이르되 이 사람이 이 거룩한 곳과 율법을 거슬러 말하기를 마지 아니하는도다
14 그의 말에 이 나사렛 예수가 이 곳을 헐고 또 모세가 우리에게 전하여 준 규례를 고치겠다 함을 우리가 들었노라 하거늘
15 공회 중에 앉은 사람들이 다 스데반을 주목하여 보니 그 얼굴이 천사의 얼굴과 같더라

