2023년 6월21일 사도행전 6장 11~15절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 사람들(11절, 15절), 스데반. 사람(11절, 13절, 14절, 15절), 모세 (11절, 14절)
4.주제만들기 : 거짓 증인들 앞에서 승리하는 스데반
5.하나님 찾기 (관찰)
-스데반을 통해 하나님 말씀을 전하게 하시는 하나님
6.인간 찾기 (관찰)
-스데반을 시기하는 거짓 증인들
-거짓 증인들 앞에서 승리하는 스데반

7.하나님 찾기 (해석) 
-하나님은 끝까지 승리하시는 분
8.인간(해석):
-시련과 위기 등이 찾아와도 거룩함을 보인 스데반 
9. 적용(나): 
-내가 생각했을 때 스데반은 가장 큰 시련이 찾아왔을 것 같다. 사람관계로부터의 스트레스는 가장 크다고 생각하기 때문이다. 단순히 상대방과 다툼이 아닌, 거짓 증인들을 매수해 사람들한테 거짓 정보를 흘렸다. 그런 와중에도 스데반은 무너지지 않고 거룩함을 지켰다. 어떻게 그럴 수 있었을까. 나는 상대방과 조금만 틀어져도 근심이 가득한데 말이다. 시련속에서 무너지지 않기 위해 나를 세상의 말들이 아닌, 하나님의 말씀으로 채워 거룩한 하나님의 제자가 되고 싶다. 
10. 영적터치(단어/구절) 천사의
얼굴
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-07', '사도행전', '7장 1절 ~ 10절', '공회에서 복음을 담대히 선포하는 스데반', '(사도행전 7장)
1 대제사장이 이르되 이것이 사실이냐
2 스데반이 이르되 여러분 부형들이여 들으소서 우리 조상 아브라함이 하란에 있기 전 메소보다미아에 있을 때에 영광의 하나님이 그에게 보여
3 이르시되 네 고향과 친척을 떠나 내가 네게 보일 땅으로 가라 하시니
4 아브라함이 갈대아 사람의 땅을 떠나 하란에 거하다가 그의 아버지가 죽으매 하나님이 그를 거기서 너희 지금 사는 이 땅으로 옮기셨느니라
5 그러나 여기서 발 붙일 만한 땅도 유업으로 주지 아니하시고 다만 이 땅을 아직 자식도 없는 그와 그의 후손에게 소유로 주신다고 약속하셨으며
6 하나님이 또 이같이 말씀하시되 그 후손이 다른 땅에서 나그네가 되리니 그 땅 사람들이 종으로 삼아 사백 년 동안을 괴롭게 하리라 하시고
7 또 이르시되 종 삼는 나라를 내가 심판하리니 그 후에 그들이 나와서 이 곳에서 나를 섬기리라 하시고
8 할례의 언약을 아브라함에게 주셨더니 그가 이삭을 낳아 여드레 만에 할례를 행하고 이삭이 야곱을, 야곱이 우리 열두 조상을 낳으니라
9 여러 조상이 요셉을 시기하여 애굽에 팔았더니 하나님이 그와 함께 계셔
10 그 모든 환난에서 건져내사 애굽 왕 바로 앞에서 은총과 지혜를 주시매 바로가 그를 애굽과 자기 온 집의 통치자로 세웠느니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 6월22일 사도행전 7장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
아브라함: 2절. 4절, 8절
하란: 2절, 4절
하나님: 3절, 4절, 6절
땅: 3절, 4절(2), 5절(2), 6절(2)
이삭: 8절(2)
야곱: 8절(2)
애굽: 9절, 10절
바로: 10절(2)

4.주제만들기 : 공회에서 복음을 담대히 선포하는 스데반
5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 공회에서 복음을 담대히 선포하는 스데반

7.하나님 찾기 (해석) 
- 스데반에게 충만히 임재하셔서 담대하고 지혜롭게 복음을 선포하게 하시는 성령님

8.인간(해석): 
- 공회에서 대제사장이 이 증언이 사실이냐 묻는 것은 사실이면 죽이겠다는 말이다. 
- 자신이 죽거나 최소한 죽기 직전까지 맞을 것을 알면서도 하나님의 역사하심, 즉 복음에 대해 담대히 선포하는 스데반.
- 이 용기는 사람의 것이 아니요, 성령님의 역사하심이다.
- 사람은 하나님이 창조하셨고, 하나님이 중생케 하시고, 하나님이 자신의 기쁘신 뜻을 위하여 마음에 소원을 주시고, 그것을 사람이 이루도록 역사하시는데, 본문에서 스데반은 성령님의 깨닫게 하심과 인도하심에 크게 기뻐하며 담대히 선포하고 있는 것으로 생각된다. 

9. 적용(나): 
- 하나님이 나를 창조하셨고, 하나님이 나를 중생케 하시고, 하나님이 자신의 기쁘신 뜻을 위하여 내 마음에 소원을 주셨다. 그런데 나는 그것을 이루고자 집중하지 못하고 있다. 어떤 면에서는 준비 기간이라고 할 수도 있으나, 준비 기간이라고 하기에는 집중하지 못하고 있는 것은 변명의 여지가 없다. 성령님께서 깨닫게 하시고 기억나게 하시는 것들을 실천해야만 한다. 

10. 영적터치(단어/구절) 
2절 여러분 부형들이여 들으소서

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-08', '사도행전', '7장 11절 ~ 20절', '하나님의 때에 언약을 이루시는 하나님」', '[행7:11-20]
11 그 때에 애굽과 가나안 온 땅에 흉년이 들어 큰 환난이 있을새 우리 조상들이 양식이 없는지라
12 야곱이 애굽에 곡식 있다는 말을 듣고 먼저 우리 조상들을 보내고
13 또 재차 보내매 요셉이 자기 형제들에게 알려지게 되고 또 요셉의 친족이 바로에게 드러나게 되니라
14 요셉이 사람을 보내어 그의 아버지 야곱과 온 친족 일흔다섯 사람을 청하였더니
15 야곱이 애굽으로 내려가 자기와 우리 조상들이 거기서 죽고
16 세겜으로 옮겨져 아브라함이 세겜 하몰의 자손에게서 은으로 값 주고 산 무덤에 장사되니라
17 하나님이 아브라함에게 약속하신 때가 가까우매 이스라엘 백성이 애굽에서 번성하여 많아졌더니
18 요셉을 알지 못하는 새 임금이 애굽 왕위에 오르매
19 그가 우리 족속에게 교활한 방법을 써서 조상들을 괴롭게 하여 그 어린 아이들을 내버려 살지 못하게 하려 할새
20 그 때에 모세가 났는데 하나님 보시기에 아름다운지라 그의 아버지의 집에서 석 달 동안 길리더니

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 6월23일 사도행전 7장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-애굽(11,12,15,17,18절), 요셉(13,14,18절), 아브라함(16,17절), 조상(11,12,15,19절)
4.주제만들기 : 하나님의 때에 언약을 이루시는 하나님」
5.하나님 찾기 (관찰)
-아브라함에게 하신 언약을 이루시기 위해 일하심
-하나님의 때가 가까워졌고 이스라엘 백성이 더욱 번성함
-하나님이 보시기에 아름다운 모세
6.인간 찾기 (관찰)
-흉년으로 곡시 없자 애굽에 곡식이 있다는 소식을 듣고 애굽으로 자손들을 보낸 야곱
-애굽의 총리 요셉이 친족에게 알려지고 바로에게 알려져 친족 75이 애굽에서 머물게 되고
-야곱은 세겜에서 장사되었고 이스라엘 백성이 번성하여 많아짐
-그 후 요셉을 알지 못하는 새 임금이 애굽 왕위에 오르고 이스라엘 백성을 괴롭힘
-그 때 모세가 났고 하나님 보시기에 아름다움
7.하나님 찾기 (해석) 
-하나님의 언약은 하나님의 때에 이루어짐. 아브라함에게 하신 언약은 아브라함 때가 아닌 요셉을 세대를 거치며 이루어졌다.
-하나님은 사람의 눈과 같이 외모로 우리를 평가하시지 않고 하나님의 눈으로 우리를 아름답게 보신다. 
8.인간(해석):
-예수님(하나님)을 알지 못하면 하나님의 언약을 이루는 주체가 아닌 잘못 사용 된 도구가 된다. 
9. 적용(나):
-하나님의 언약은 반드시 이루어진다. 구약에 쓰여진 것처럼 구원자이신 예수님이 우리에게 분명히 나타나셨다. 그것을 믿는 사람은 하나님의 은혜이며 하나님의 축복이자 선물인 것이다. 그런데 하나님을 믿지 않는 사람들도 많다. 하나님을 믿지 않을 만한 충분한 이유(그들만의)가 이 세상엔 너무 많다. 그럼으로 우리는 전도를 해야되며 성령님께서 그 마음을 변화시켜주도록 기도해야 한다.  
-사람을 외모(그 외 직위 등등)로 판단하지 말고 하나님의 눈으로 바라볼 수 있도록 기도한다.
10. 영적터치(단어/구절) : 하나님 보시시에 아름다운지라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-09', '사도행전', '7장 21절 ~ 30절', '제목 없음', '(사도행전 7장)
21. 버려진 후에 바로의 딸이 그를 데려다가 자기 아들로 기르매
22. 모세가 애굽 사람의 모든 지혜를 배워 그의 말과 하는 일들이 능하더라
23. 나이가 사십이 되매 그 형제 이스라엘 자손을 돌볼 생각이 나더니
24. 한 사람이 원통한 일 당함을 보고 보호하여 압제 받는 자를 위하여 원수를 갚아 애굽 사람을 쳐 죽이니라
25. 그는 그의 형제들이 하나님께서 자기의 손을 통하여 구원해 주시는 것을 깨달으리라고 생각하였으나 그들이 깨닫지 못하였더라
26. 이튿날 이스라엘 사람끼리 싸울 때에 모세가 와서 화해시키려 하여 이르되 너희는 형제인데 어찌 서로 해치느냐 하니
27. 그 동무를 해치는 사람이 모세를 밀어뜨려 이르되 누가 너를 관리와 재판장으로 우리 위에 세웠느냐
28. 네가 어제는 애굽 사람을 죽임과 같이 또 나를 죽이려느냐 하니
29. 모세가 이 말 때문에 도주하여 미디안 땅에서 나그네 되어 거기서 아들 둘을 낳으니라
30. 사십 년이 차매 천사가 시내 산 광야 가시나무 떨기 불꽃 가운데서 그에게 보이거늘

