2023년 6월24일 사도행전 7장21절~30절

1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
모세: 22절 25절 26절 27절 29절 30절
이스라엘 백성: 23절 25절 26절(2) 27절
애굽사람: 22절 28절
