4. 주제 만들기
나그네된 모세
5.하나님 찾기 (관찰)

6.인간 찾기(관찰)
모세의 생애를 설명하는 스데반
버려진 아기모세
왕족으로 길러진 모세
애굽인을 쳐 죽인 모세
동족에게 배신 당하는 모세
나그네 인생이 된 모세

7.하나님 찾기(해석)

8. 인간 찾기(해석)
스데반 집사는 사도도 아닌 집사 직분임에도 모세의 생애를 간략하면서도 인상깊게 정리할정도로 하나님 말씀에 깊이가 있는지를 볼수있다. 그가 설명하고 있는 모세는 인간적인 애굽귀족으로 동족인 이스라엘  백성을 도우려 했지만 동족의 배반으로 나그네  되는것을 비추었다. 진정한 도움과 구원은 하나님 으로부터 시작됨을 나타내는듯 하다.
 
9. 적용(나)
하나님 의 도움이 없이는 그저 힘없는 나그네 인생이 되는것을 배운다. 더욱 주님께 더욱 메달리는 인생이 되야겠다.
