7.하나님 찾기(해석)
혈기왕성하고 정의감이 넘치는 모세가 이제는 오랜 40년의 목동생활을 통하여 누구에게도 주목받지않는 노인이됐다. 그러한 모세에게 하나님은 이스라엘백성을 해방시킬 지도자로 모세를 지목하셨다. 하나님은 마음만 먹으시면 마른나무도 생기를 부어 쓰실수있는 전능하신  하나님 이시다.

8. 인간 찾기(해석)
하나님은 이스라엘백성이 애굽의로의 노예생활이 힘들어 탄식하며 하나님께 도움의 탄식을  한다. 그 탄식을 들으시고 하나님은 모세를 통하여 그들의 해방 계획을 세우신다. 그러한 하나님계획에 모세는 인간적인 약한모습을 보이며 거절한다. 그러한 모세임에도 하나님의 능력을 체험한 모세는 인도의 길을 나선다. 이스라엘 백성은 모세가 시내산에 내려옴이 늦어짐에 모세의 형 아론과  더불어 그들이 자체적으로 인도할 신 즉 우상  만들것을 상의한다. 크신 하나님의 큰 그림을 알지못하고 무지하고 죄성먛은 인간의 본성과 나약함을 본다.
 
9. 적용(나)
능력이 없고  나약해보여도 하나님이 사용하신다면 누구든지 귀하게 사용받게 되는것을 본다. 나도 더욱 주님의  능력을 의지하며 감사하며 살아야겟다.  그리고 겸손한 사람이 되야겠다.
