4.주제만들기: 하나님을 바라는 삶
5.하나님 찾기 (관찰)
- 우상 숭배하는 이스라엘을 외면하시는 하나님
- 모세에게 증거의 장막을 만들게 하시되, 명하신 양식대로 만들게 하심
- 하나님은 인간이 만든 처소가 필요한 분은 아님

6.인간 찾기 (관찰)
- 송아지를 만들어 그 우상 앞에 제사하며 자기 손으로 만든 것을 기뻐하는 이스라엘 백성들
- 증거 장막을 이방인의 땅을 점령할 때에 여호수아와 함께 가지고 들어가서 다윗 때까지 이름
- 다윗이 하나님의 처소를 준비하게 하여 달라고 기도함
- 솔로몬이 하나님을 위하여 집을 지음

7.하나님 찾기 (해석) 
- 이스라엘 백성들이 광야에서 사십 년간 하나님을 위해 희생과 제물을 바친 적이 없는데 우상을 위해서 바치는 모습을 보며 괴로워하심
- 이스라엘 백성과 함께 함을 보여주기 위해 그들의 진중에 장막을 치게 하시고 그곳에 임재하신 하나님
- 다윗이 하나님께 사랑받고 자신도 하나님을 사랑하여 하나님이 거하실 성전을 궁전보다 멋지게 지어드리고 싶었고, 그것을 솔로몬이 지었으나 하나님은 그 사랑의 행위는 받으시되 성전에만 거하시는 분이 아님을 분명히 말씀하심. 왜냐하면 하나님은 온 세상을 창조하신 분이기 때문임. 우리가 아는 만큼이 주님의 전부가 아니라는 것임. 우리가 아는 것은 바다의 모래알 한 알갱이의 천억 분의 일 크기도 안 됨.

8.인간(해석): 
- 자신들의 눈에 보이는 하나님을 섬기고 싶어 송아지를 만든 이스라엘 백성들. 이들은 자신의 눈에 보이고 자신의 정욕을 원 없이 채워줄 하나님을 바라고 있음. 그것은 하나님이 아니라 자기가 하고 싶은 대로 하려는 인간의 탐욕이며 하나님을 떠나 살고 싶어하는, 하나님의 통치를 벗어나고 싶어하는 인간의 죄성임.
- 하나님의 임재의 증거인 증거 장막을 모세 때부터 여호수아, 그리고 다윗 때까지 함께 함. 이것은 하나님의 동행하심을 의미함. 그들이 원하든지 원하지 않든지 하나님은 이스라엘 백성과 늘 함께 하셨고, 지도자를 통하여 백성들이 자신을 바라보도록 지도하시고 인도하심.
-  다윗이 하나님께 사랑받고 자신도 하나님을 사랑하여 하나님이 거하실 성전을 궁전보다 멋지게 지어드리고 싶었고, 그것을 솔로몬이 지음.

9. 적용(나): 
- 동행하시는 하나님을 바라보며 늘 주님과 대화하는 삶을 살아내고 있는가? 교제가 부족하고, 나의 내면에 하나님 임재 의식이 부족하다. 사람의 본분과 기본에 충실해야 한다. 

