5.하나님 찾기 (관찰)
-스데반에게 하나님의 영광과 우편에 계신 예수님의 모습을 보이심
6.인간 찾기 (관찰)
- 스데반 : 복음을 강력히 전하고 율법을 어기고 예수님을 죽인 일에 대해 담대히 말함
- 유대인 : 마음에 찔려 이를 갈고, 귀를 막고 달려들어 돌로 스데반을 쳐 죽임
7.하나님 찾기 (해석) 
- 자신을 보이시며 스데반을 담대케 하시고, 위로하시고, 축복하신 하나님
8.인간(해석):
- 스데반은 담대하고 정확하게 예수님을 전하였다. 그들의 죄로 인해 예수님을 십자가에 매단 것까지 말할 정도로 담대했다. 스데반은 죽을 각오로 예수님을 전했다. 그런 스데반에게 하나님은 나타나셨다. 
- 스데반의 말에 유대인들, 제사장들, 서기관들 등이 마음에 찔려했다. 잘못된 행동에 대한 찔림에 돌이키기 보단 이를 간다. 그리고 다같이 스데반을 돌로쳐 죽였다. 죄에서 돌이키긴 어렵다. 자신의 죄를 숨기기 위해 또 다른 죄를 짓게 되는 어리석은 선택을 한다.
9. 적용(나): 
-돌에 맞은 스데반의 모습을 상상해보려 하는데 잘되지 않는다. 얼마나 참혹했을까...  그런데 그 와중에 기도를 한다. 하나님께 자신이 돌로 친 자들의 죄를 용서해달라고 말한다. 그리고 죽는다. 예수님의 사랑을 실천하는 것은 어렵지 않다. 가식으로라도 예수님의 사랑인척 할 수 있다. 그런데 죽음 앞에서도 예수님의 사랑을 보여주는건 성령이 충만했기에 가능했을 것이다.
-하나님을 더 사랑하고 이웃을 내 자신과 같이 사랑해야겠다. 스데반과 같은 사랑이 나에게도 가득임하길 기도한다. 
-마포대교 노방전도가 복음의 씨앗이 되길 기도한다.
