7.하나님 찾기(해석)
스데반의 죽음 이후에 사람들은 흩어진다. 흩어짐 속에서도 사람들에게  복음을 전파케 하시는 하나님을 발견한다. 즉 디아스포라의 모습을 볼수있다. 

8. 인간 찾기(해석)
핍박당하는 중에도 복음을 전파하는 사람들을 본다. 재미있는 것은 신약에 등장하는  복음의 대가 사도바울도 등장한다. 그때는 사울바울은 아직 주님을 만나기전이라 믿는사람을 핍박하고 옥에 보내는데 앞장서고있다. 스데반이 죽을당시 죄를 그들에게 넘기지 마라고 하나님께 부탁드린것이 마치 사울청년이 나중에  회개하고 위대한 복음의 사람으로 사용될것을 미리 알고 외친것이라 여겨진다. 한편 핍박이나 흩어짐이 있더라도 복음의움직임을 막을 대상은 없다.  그러한 하나님이 기뻐하시는 복음이 전파될때 표적은 보너스로 하나님이 주신다.
 
9. 적용(나)
생명의 복음을 열심히 전하는 일꾼이 되야겠다 
10. 영적터치(단어/구절)
4절: 그 흩어진 사람들이 두루 다니며 복음의 말씀을 전할새

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-14', '사도행전', '8장 11절 ~ 20절', '돈으로 살 수 없는 하나님의 권능과 선물', '(사도행전 8장)
11 오랫동안 그 마술에 놀랐으므로 그들이 따르더니
12 빌립이 하나님 나라와 및 예수 그리스도의 이름에 관하여 전도함을 그들이 믿고 남녀가 다 세례를 받으니
13 시몬도 믿고 세례를 받은 후에 전심으로 빌립을 따라다니며 그 나타나는 표적과 큰 능력을 보고 놀라니라
14 예루살렘에 있는 사도들이 사마리아도 하나님의 말씀을 받았다 함을 듣고 베드로와 요한을 보내매
15 그들이 내려가서 그들을 위하여 성령 받기를 기도하니
16 이는 아직 한 사람에게도 성령 내리신 일이 없고 오직 주 예수의 이름으로 세례만 받을 뿐이더라
17 이에 두 사도가 그들에게 안수하매 성령을 받는지라
18 시몬이 사도들의 안수로 성령 받는 것을 보고 돈을 드려
19 이르되 이 권능을 내게도 주어 누구든지 내가 안수하는 사람은 성령을 받게 하여 주소서 하니
20 베드로가 이르되 네가 하나님의 선물을 돈 주고 살 줄로 생각하였으니 네 은과 네가 함께 망할지어다
