4.주제만들기: 돈으로 살 수 없는 하나님의 권능과 선물
5.하나님 찾기 (관찰)


6.인간 찾기 (관찰)
- 시몬의 마술을 따르던 사람들
- 빌립의 전도로 세례를 받은 사람들
- 표적과 큰 능력을 보고 놀라는 시몬
- 사마리아로 온 베드로와 요한
- 믿기로 한 자들이 성령 받기를 위해 기도한 후 안수하는 베드로와 요한
- 권능을 내게도 주어 누구든지 내가 안수하는 사람은 성령을 받게 해달라고 돈을 주며 요구하는 시몬
- 네가 하나님의 선물을 돈 주고 살 줄로 생각하였으니 네 은과 네가 함께 망할것이라고 말하는 베드로

7.하나님 찾기 (해석) 
- 예수님을 순수하게 바라고 믿는 자들에게 성령을 보내주시는 하나님.

8.인간(해석): 
- 신기한 현상을 보면 사람들은 그것을 따름
- 마술을 능가하는 성령님의 능력을 보고 전도하는 빌립에게 믿음의 고백을 하고 세례를 받은 사마리아인들
- 사마리아인들이 침례 받았다함을 듣고 성령을 받게 하기 위해 기도하는 베드로와 요한. 이들은 성령님을 받는 것은 하나님께 달려 있음을 확실히 알고 있음.
- 믿는 자들은 성령을 받기를 바라며 하나님께 기도해야 함.
- 두 사도가 안수하자 성령이 임하는 것을 본 시몬은 그 능력을 돈 주고 사려고 함. 성령님의 능력을 돈 주고 살 수 있다고 생각한 것도 문제이지만, 그런 능력의 소유자로 사람들에게 높임을 받으려는 허영심과 하나님의 영광을 가로채려는 그 마음이 문제임
- 시몬의 죄를 정확히 지적하는 베드로. 성령으로 충만하여 성령님이 시몬을 분별케 하신 것으로 생각됨. 

9. 적용(나): 
- 눈에 보이는 것에 현혹되지 않으려 노력하지만 눈에 보이는 것에 현혹되고 있는 나를 발견하곤 한다. 깨어 기도하되, 성령 안에서 기도하여 현혹되지 않도록 주의해야 한다. 헛된 영광을 바라거나 하나님의 영광을 가로채려는 교만을 버리고 오직 하나님을 바라는 자가 돼야만 한다. 헛된 영광을 바라는 자와 정의롭지 못한 자를 분별하고 교육할 수 있어야 하겠고, 필요하다면 그와 동행하지 않는 결단도 필요하겠다.
- 성령님을 받지 못한 형제 자매들이 성령 받기를 위해 기도해야 한다. 

10. 영적터치(단어/구절) 
15절 그들을 위하여 성령 받기를 기도하니

11. 믿음과 회개 및 감사기도로 마무리', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-15', '사도행전', '8장 21절 ~ 30절', '하나님께 회개하지 않는 어리석음', '[행8:21-30]
21 하나님 앞에서 네 마음이 바르지 못하니 이 도에는 네가 관계도 없고 분깃 될 것도 없느니라
22 그러므로 너의 이 악함을 회개하고 주께 기도하라 혹 마음에 품은 것을 사하여 주시리라
23 내가 보니 너는 악독이 가득하며 불의에 매인 바 되었도다
24 시몬이 대답하여 이르되 나를 위하여 주께 기도하여 말한 것이 하나도 내게 임하지 않게 하소서 하니라
25 두 사도가 주의 말씀을 증언하여 말한 후 예루살렘으로 돌아갈새 사마리아인의 여러 마을에서 복음을 전하니라
26 주의 사자가 빌립에게 말하여 이르되 일어나서 남쪽으로 향하여 예루살렘에서 가사로 내려가는 길까지 가라 하니 그 길은 광야라
27 일어나 가서 보니 에디오피아 사람 곧 에디오피아 여왕 간다게의 모든 국고를 맡은 관리인 내시가 예배하러 예루살렘에 왔다가
28 돌아가는데 수레를 타고 선지자 이사야의 글을 읽더라
29 성령이 빌립더러 이르시되 이 수레로 가까이 나아가라 하시거늘
30 빌립이 달려가서 선지자 이사야의 글 읽는 것을 듣고 말하되 읽는 것을 깨닫느냐

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
