1:감동받는 단어나 구절 찾기(영적터치)

2023년 6월30일 사도행전 8장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-마음(21,22절), 악(22,23절), 일어나(26,27절), 수레(28,29절)
4.주제만들기 : 하나님께 회개하지 않는 어리석음
5.하나님 찾기 (관찰)
-광야로 사도들은 이끄시는 성령님
-수레로 나아가라고 말하시는 성령님
6.인간 찾기 (관찰)
-시몬의 마음이 바르지 못하다는 것을 지적하며 회개하라는 사도들
-자신이 기도하지 않으면서 자신을 위한 기도를 요구하는 시몬
-예루살렘으로 돌아와 사마리아인의 여러마을에 복음을 전하는 사도들
-성령님의 말씀에 순종하며 광야로 나아가 수레로 달려가는 빌립 
7.하나님 찾기 (해석) 
-에디오피아의 국고를 맡은 관리가 예루살렘까지 예배하러 오자 간절히 하나님을 찾는 사람에게 역사하시는 하나님
8.인간(해석):
-사도들은 시몬에게 정확히 무엇이 잘못되었는지 알려준다. 그러나 시몬은 자신이 직접 회개하지 않고 제자들에게 자신의 기도를 부탁한다. 
-사도들은 계속해서 복음을 전한다. 예수님을 조금이라도 빨리 전하고 싶었을 것이다. 그런데 갑자기 성령님께서 광야로 보내신다. 성령님의 지시에 제자들은 순종하며 수레로 나아가라는 명령에 달려간다.
9. 적용(나): 
-시몬은 이 시대에 최초로 자신을 하나님이라고 자칭한 이단 교주로 알고 있다. 인간의 완악함은 무섭다. 사도들이 시몬의 속마음을 알고 회개하라고 했으나 시몬은 받아들이지 않았다. 오히려 자신을 위해 기도를 부탁하는 안하무인격의 태도를 보인다. 그런 완악함은 자신을 신으로 만들어 수많은 영혼을 괴롭혔을 것이다. 현재 내가 가지고 있는 죄악들도 나 스스로를 신으로 만드는 자기합리화의 태도로 돌이키지 못하는 것들이 많다. 내 안에 있는 죄를 간절히 돌이키고 회개할 줄 아는 삶을 살길 원한다.
-제자들은 바쁘게 움직였다. 예수님을 전한다는 것은 그런 것 같다. 단 한사람이라도 더 예수님을 알게 하기 위해 제자들이 얼마나 부단히 움직였을까 생각한다. 그리고 얼마나 지쳐있었을까... 그런데 성령님은 예루살렘을 벗어나 광야로 나가게 하신다. 아무것도 없는 광야로 왜 나가게 하셨을까? 우리가 알지 못하는 하나님의 계획이 너무 많다. 그것에 순종하는지 순종하지 않는지 점검해야겠다. 
-순종한 제자들은 광야에 가서 에티오피아의 관원을 만난다. 수레로 나아가라는 성령님의 말씀에 빌립은 달려간다. 움직이는 수레를 따라가려면 얼마나 달려야했을까? 전력으로 질주했을지도 모른다. 내가 해낼 수 없을 것 같은 하나님의 명령에 나는 과연 순종할 수 있을까? 생각해본다. 하나님의 명령에 순종했을 때 나타나는 역사를 경험하고 싶다.
-노방전도는 나에게 너무 힘든 일이다. 웃으며 전도지를 나눠주기 너무 힘들다. 그럼에도 전도를 해야한다. 단 한명이라도 예수님을 알 수 있도록, 힘들고 지친 영혼이 예수님의 품에 들어와 쉴 수 있도록 해야만 한다. 나도 웃으며 예수 믿으세요라고 말할 수 있는 날이 빨리 왔음 좋겠다.
10. 영적터치(단어/구절) : 빌립이 달려가서
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-16', '사도행전', '8장 31절 ~ 40절', '제목 없음', '(사도행전 8장)
31. 대답하되 지도해 주는 사람이 없으니 어찌 깨달을 수 있느냐 하고 빌립을 청하여 수레에 올라 같이 앉으라 하니라
32. 읽는 성경 구절은 이것이니 일렀으되 그가 도살자에게로 가는 양과 같이 끌려갔고 털 깎는 자 앞에 있는 어린 양이 조용함과 같이 그의 입을 열지 아니하였도다
33. 그가 굴욕을 당했을 때 공정한 재판도 받지 못하였으니 누가 그의 세대를 말하리요 그의 생명이 땅에서 빼앗김이로다 하였거늘
34. 그 내시가 빌립에게 말하되 청컨대 내가 묻노니 선지자가 이 말한 것이 누구를 가리킴이냐 자기를 가리킴이냐 타인을 가리킴이냐
35. 빌립이 입을 열어 이 글에서 시작하여 예수를 가르쳐 복음을 전하니
36. 길 가다가 물 있는 곳에 이르러 그 내시가 말하되 보라 물이 있으니 내가 세례를 받음에 무슨 거리낌이 있느냐
37. (없음)
38. 이에 명하여 수레를 멈추고 빌립과 내시가 둘 다 물에 내려가 빌립이 세례를 베풀고
39. 둘이 물에서 올라올새 주의 영이 빌립을 이끌어간지라 내시는 기쁘게 길을 가므로 그를 다시 보지 못하니라
