9. 적용(나)
악행자 사울이 용서받고 위대한 바울이 됐듯이 사람은 주님의 은혜가 있다면 누구나 바뀔수가 있음을 발견한다. 나같은 죄인을 용서하시고 사용하시는 크신  주님처럼 내 이웃을 사랑하며 살아야겠다.
