베드로(시몬): 5(2), 9

4.주제만들기: 하나님을 경외하는 자
5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 경건하여 온 집안과 더불어 하나님을 경외하는 고넬료
- 하나님의 사자를 만나 하나님의 말씀을 듣는 고넬료
- 집안 하인 둘과 부하 가운데 경건한 사람을 욥바로 보내는 고넬료
- 욥바에 가까이 가는 세 사람
- 기도하러 기둥에 올라가 환상을 보는 베드로

7.하나님 찾기 (해석) 
- 이방인 고넬료가 베드로를 만나게 하시는 하나님. 하나님은 자신을 경외하는 자는 이방인이나 이스라엘인이나 상관없이 구원하시는 하나님. 이방인도 구원 계획이 있음을 아브라함 때부터 말씀하셨으나 깨닫지 못하는 이스라엘 백성들, 그 중에서 제자들에게 고넬료를 통해 확실히 말씀하시기 위해 고넬료를 베드로에게 보내시는 하나님.
- 고넬료에게만 환상을 주시는 것이 아니라 고넬료를 만날 베드로에게도 환상을 주시는 하나님. 하나님은 사람을 통해 역사하실 때에 만나게 하는 사람들에게 감동을 주신다.

8.인간(해석): 
- 경건하여 하나님을 경외하되 온 집안과 더불어 하나님을 경외한 고넬료. 고넬료는 하나님을 믿는 것이 생명의 길임을 분명히 알았던 것이다. 고넬료는 여기서 멈추지 않고 백성을 많이 구제하고 하나님께 항상 기도하는 삶을 살았다. 이것으로 미루어 볼 때 고넬료에게는 성령님의 중생하심이 있었던 것으로 보인다. 항상 기도함으로 성령님의 마음을 느끼고 그것을 실천하는 삶을 살았던 것이다.
- 하나님의 명령을 실행하되, 그 일을 경건한 자에게 맡긴 고넬료. 이 것을 미루어 보아 군대에서 일을 할 때에도 경건한 자와 함께 교제하며 정직하고 정의롭게 일을 했을 것이다.
- 하나님을 사랑하여 정해진 시간에 조용한 곳에 가 하나님께 기도하는 베드로. 베드로는 이러한 삶을 멈추지 않았을 것이다.

9. 적용(나): 
- 하나님을 경외하여 항상 기도하고 이웃을 구제한 고넬료와 날마다 하나님께 기도한 베드로를 본받아야 한다. 그리고 겸손해야 한다.

10. 영적터치(단어/구절) 
2 그가 경건하여 온 집안과 더불어 하나님을 경외하며 백성을 많이 구제하고 하나님께 항상 기도하더니

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-22', '사도행전', '10장 11절 ~ 20절', '환상에 대해 깊이 생각하는 베드로', '[행10:11-20]
11 하늘이 열리며 한 그릇이 내려오는 것을 보니 큰 보자기 같고 네 귀를 매어 땅에 드리웠더라
12 그 안에는 땅에 있는 각종 네 발 가진 짐승과 기는 것과 공중에 나는 것들이 있더라
13 또 소리가 있으되 베드로야 일어나 잡아 먹어라 하거늘
14 베드로가 이르되 주여 그럴 수 없나이다 속되고 깨끗하지 아니한 것을 내가 결코 먹지 아니하였나이다 한대
15 또 두 번째 소리가 있으되 하나님께서 깨끗하게 하신 것을 네가 속되다 하지 말라 하더라
16 이런 일이 세 번 있은 후 그 그릇이 곧 하늘로 올려져 가니라
17 베드로가 본 바 환상이 무슨 뜻인지 속으로 의아해 하더니 마침 고넬료가 보낸 사람들이 시몬의 집을 찾아 문 밖에 서서
18 불러 묻되 베드로라 하는 시몬이 여기 유숙하느냐 하거늘
19 베드로가 그 환상에 대하여 생각할 때에 성령께서 그에게 말씀하시되 두 사람이 너를 찾으니
20 일어나 내려가 의심하지 말고 함께 가라 내가 그들을 보내었느니라 하시니

[샘플]
