2023년 7월7일 사도행전 10장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-속되다(14,15절), 깨끗하지 아니한(14,15절), 환상(17,19절), 소리(13,15절)
4.주제만들기 : 환상에 대해 깊이 생각하는 베드로
5.하나님 찾기 (관찰)
-환상으로 베드로에게 말씀하시는 성령님
6.인간 찾기 (관찰)
-꿈에서 환상을 보고 불결하고 더러운 음식은 먹지 못하겠다는 베드로
-하나님이 깨끗하게 하신 것을 불결하다고 말하지 말라는 세번의 환상에 깊이 고민하는 베드로
7.하나님 찾기 (해석) 
-3의 트라우마를 활용해 베드로를 변화시키시는 유머러스한 하나님. 이방인에 대한 전도가 중요함을 인식시키기 위해 3번 강조하여 말씀하신 것 같다
8.인간(해석):
-베드로는 세번이나 거절할 정도로 짐승들이
아주 다양하고 우리가 먹지 않는 종류였던 것 같다. 그 당시 이방인에 대한 유대인의 태도가 그랬을지 모르겠다. 어찌 됐든 3의 트라우마 덕분에 베드로는 환상에 대해 깊이 고민한다. 그러자 성령님이 임하신다. 
9. 적용(나): 
- 하나님께서 내게도 같은 상황을 연출하신다면 얼마나 괴로울까? 말도 안되는 순종을 바라는데 이거 진짜 순종해야 되나라는 생각이 들거다. 그럼에도 순종을 바라실 때 깊이 기도하고 성령님의 인도하심을 따라야겠다. 
- 마포대교 노방전도를 처음 기획 했을 때 스포츠 선교와 다른 노선의 선교를 해야된다는게 마음으론 이해해도 머리가 이해되지 않았다. 그런데 마포대교에 노방전도로 순종했더니 하나님은 우리에게 깊은 감동의 은혜를 선물해주신다. 마포대교 노방전도는 너무 좋다. 그러나 나는 아직 말한마디 못 붙이겠다. 
10. 영적터치(단어/구절) : 환상이 무슨 뜻인지 의아해 하더니 
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

