- 베드로에게 며칠 더 머물러 달라 요청하는 사람들.

7.하나님 찾기 (해석) 
- 이방인에게도 성령님을 부어주심으로써 예수님을 믿는 사람들은 누구든지 예수님의 이름을 힘입어 죄 사함을 받고 구원받을 수 있음을 알려주시는 하나님

