- 구원은 이스라엘에게만 주어지는 것이라 생각했기에 이방인에게 성령님을 보내주신 것은 제자들에게도 놀라운 큰 사건이었음
- 이 기쁨을 베드로와 함께 누리기 위해 베드로가 며칠 더 머물러 주기를 요청함. 이 요청을 받은 베드로도 며칠 더 머무르는 것이 기뻤을 것이라 생각됨.

9. 적용(나): 
- 성령님을 체험하고 다른 이들에게도 성령님을 체험하게 하는 하나님의 능력이 드러나는 삶을 살고 싶다. 그러기 위해 오늘부터 힘을 내어 성령 안에서 깨어 기도해야겠다.

