8.인간(해석):
-유대인들만 선택받은 백성이라 생각한 사도와 제자들은 베드로의 행동을 비난했다. 그러나 그것은 하나님의 뜻이 아니었기에 베드로를 사용해 그들의 닫힌 사고를 열어주신다. 베드로를 사용하신 이유는 그가 사도들 중에 리더였기 때문에 또는 행동 중심의 성향으로 이방인에 적대적 태도를 가장 강하게 가지고 있는 제자였을 수도 있다. 베드로가 변화되고 제자들에게 설명을 하자 제자들은 받아들인다. 
9. 적용(나): 
