4.주제만들기: 이방인에게도 본격적으로 확산되는 복음
5.하나님 찾기 (관찰)
- 그브로와 구레네 디아스포라들과 함께 하신 성령님
- 선지자 아가보에게 감동을 주시고 예언하게 하시는 성령님

6.인간 찾기 (관찰)
- 주를 믿고 돌아온 수많은 사람들
- 예루살렘 교회에서 안디옥에 파송된 바나바
- 바울을 찾아 데리고 온 바나바
- 안디옥 교회에서 1년간 큰 무리를 가리침
- 제자들이 안디옥에서 비로소 그리스도인이라 일컬음을 받게 됨
- 아가보라 하는 한 사람이 일어나 성령으로 말하되 천하에 큰 흉년이 들리라 예언하였고 그대로 됨
- 안디옥 교회에서 유대에 연보하기로 작정하고 바나바와 바울을 통해 보냄

7.하나님 찾기 (해석) 
- 디아스포라를 통해 이방인에게도 복음을 전하게 하시는 성령님
- 아가보를 통해 흉년을 예고하시고 믿는 자들이 서로를 돕게 하시는 성령님

8.인간(해석): 
- 성령의 감동으로 복음을 전하는 디아스포라들. 이들의 능력이 아니라 주님의 손이 함께 하시매 이방인들이 주님을 믿고 주께 돌아옴.
- 안디옥 교회에 파송된 바나바는 이방인에게도 복음이 전파되고 그들이 주님을 믿는 것을 보고 많이 기뻐했다. 
- 주님의 은혜가 있는 곳과 복음을 믿는 곳에는 기쁨이 넘친다.
- 바나바는 이방인에게 복음을 전하기로 택하심 받은 바울을 데려왔고 교회에서 일 년간 큰 무리를 가르쳤는데, 이 때의 바나바와 바울은 기쁨으로 충만했을 것이다. 성령님이 함께 하시고 은혜가 있는 곳에는 세상이 알 수 없는 기쁨으로 충만한 것이다. 
- 예수님의 제자들은 이제 유대인 아니라 그리스도인이라 일컬음을 받게 되었다. 예수님을 주님으로 모시고 성령님의 감동으로 사는 사람들의 모습은 세상에서 감당할 수 없다.
- 하나님의 능력을 경험하고 그 능력으로 서로 사랑하게 된 자들을 서로를 돕고자 하는 마음이 일어나고, 어려움이 있을 때 최선을 다해 돕는다. 

9. 적용(나): 
- 복음이 전파되는 모습을 보며 기뻐하고 싶다. 이 기쁨에 동참하기 위해서는 복음을 전하고 말씀을 바르게 가르치는 일에 더 힘을 내야 할 것이다. 힘써 기도하며 성령님의 은혜를 구해야겠다. 성령님의 은혜 없이는 일어나지 않는 일이기 때문이다.

10. 영적터치(단어/구절) 
23 하나님의 은혜를 보고 기뻐하여 모든 사람에게 굳건한 마음으로 주와 함께 머물러 있으라 권하니

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-06-29', '사도행전', '12장 1절 ~ 10절', '중보 기도의 능력', '[행12:1-10]
1 그 때에 헤롯 왕이 손을 들어 교회 중에서 몇 사람을 해하려 하여
2 요한의 형제 야고보를 칼로 죽이니
3 유대인들이 이 일을 기뻐하는 것을 보고 베드로도 잡으려 할새 때는 무교절 기간이라
4 잡으매 옥에 가두어 군인 넷씩인 네 패에게 맡겨 지키고 유월절 후에 백성 앞에 끌어 내고자 하더라
5 이에 베드로는 옥에 갇혔고 교회는 그를 위하여 간절히 하나님께 기도하더라
6 헤롯이 잡아 내려고 하는 그 전날 밤에 베드로가 두 군인 틈에서 두 쇠사슬에 매여 누워 자는데 파수꾼들이 문 밖에서 옥을 지키더니
7 홀연히 주의 사자가 나타나매 옥중에 광채가 빛나며 또 베드로의 옆구리를 쳐 깨워 이르되 급히 일어나라 하니 쇠사슬이 그 손에서 벗어지더라
8 천사가 이르되 띠를 띠고 신을 신으라 하거늘 베드로가 그대로 하니 천사가 또 이르되 겉옷을 입고 따라오라 한대
9 베드로가 나와서 따라갈새 천사가 하는 것이 생시인 줄 알지 못하고 환상을 보는가 하니라
10 이에 첫째와 둘째 파수를 지나 시내로 통한 쇠문에 이르니 문이 저절로 열리는지라 나와서 한 거리를 지나매 천사가 곧 떠나더라

