5.하나님 찾기 (관찰)
- 옥에 갇힌 베드로에게 천사를 보내심
6.인간 찾기 (관찰)
- 헤롯은 야고보를 칼로 죽이고 유대인들이 기뻐하는 것을 보자 베드로를 죽이려고 옥에 가둠
