- 베드로는 꿈인지 생신지 모르지만 환상 같은 상황에서 천사의 지시대로 따름
7.하나님 찾기 (해석) 
- 하나님의 때가 아직이기에 베드로는 순교에 처할 위기에서 천사들의 도움으로 위기를 벗어나게 된다.
8.인간(해석):
- 대중에게 인기를 끌기 위해 진실과 진리를 거부한 헤롯은 야고보를 죽이고도 베드로까지 죽이려 한다. 사람 한명을 죽이기 위해 4명이 4개조로 감시하게 하고, 잠 잘 때도 군인 두명 사이에서 재웠으며 쇠사슬로 묶었다. 아마도 지난번 옥에서 나온 사건이 큰 이슈가 되었나보다. 그리고 헤롯도 그것이 사실일지 시험해보고 싶었던 것 같다. 바로 죽이면 되었을 것을 왜 군인을 저렇게 많이 배치하고 감시했을까?
9.적용(나): 
- 어려운 상황에 처한 이웃을 위해 간절히 기도하는 마음이 생기길 바란다. 요즘 내 일이 아니거나, 나와 큰 친분이 없는 상황들에 대해서 너무 쉽게 무시하는 교만함이 있다. 중보 기도의 능력이 하나님의 때에 발휘되도록 기도에 동참해야겠다. 
10.영적터치(단어/구절) : 기뻐하는 것을 보고
11.믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

