2023년 7월17일 사도행전 13장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
바나바: 1, 2, 7
사울(바울): 1, 2, 7, 9
주: 2, 10
금식: 2, 3
하나님의 말씀: 5, 7
유대인: 5, 6
마술사: 6, 8(2)
총독: 7, 8
서기오 바울: 7(2)

4.주제만들기: 구브로로 파송된 바나바와 바울
5.하나님 찾기 (관찰)
- 바나바와 사울을 따로 세우라 명하신 성령님

6.인간 찾기 (관찰)
- 주를 섬겨 금식 기도하는 선지자와 교사들
- 성령님의 명령대로 바나바와 사울 두 사람에게 안수하고 보내는 교사들
- 구브로 살라미의 여러 회당에서 하나님의 말씀을 전하는 바나바와 사울
- 거짓 선지자인 마술사를 만남
- 서기오 바울이 바나바와 사울을 불러 하나님의 말씀을 듣고자 함
- 마술사가 총독이 하나님의 말씀을 믿지 못하게 힘씀
- 바울이 성령이 충만하여 마술사를 주목하고 꾸짖음

7.하나님 찾기 (해석) 
- 바나바와 사울을 복음 전도자로 택하시고 구브로에 보내시는 성령님
- 성령님의 사역을 비추어 볼 때 하나님께서는 백성을 중생하신 후에 회개한 자들이 전도하기를 바라신다.
- 하나님은 말씀이 선포되는 것을 막는 마귀의 세력을 대적하시고, 우리도 마귀를 대적하기를 원하신다.

8.인간(해석): 
- 하나님을 사랑하여 금식으로 기도하는 선지자와 교사들
- 성령님의 명령에 순종하여 바나바와 사울을 세우되, 금식으로 기도하고 그 후 안수하여 보내는 선지자와 교사들
- 위험을 무릎서고 배를 타고 구브로 섬에 가서 하나님의 말씀을 전하는 바나바와 사울
- 하나님의 말씀을 듣고 싶어하는 총독 서기오 바울. 이 바울은 말씀을 듣고 하나님을 믿는 또 다른 그리스도인이 될 것이다. 이를 방해하는 마술사는 자기가 계속 구브로에서 선지자 역할을 하며 총독의 오른팔로 또는 비선으로 남고 싶었을 것이다. 그래서 총독이 믿지 못하게 방해를 했으나 이것은 마귀의 짓이며 성령님의 사역을 방해하는 것이었다.
- 바울이 성령 충만한 가운데 하나님의 말씀이 전파됨을 방해하는 마귀의 역사를 대적하며 꾸짖음.

9. 적용(나): 
- 하나님을 경외하여 금식으로 기도하고 주시는 말씀에 순종하며 살아가야 한다. 아들이 태어 나고 아들 밥 먹이다가 금식 기도에 한 두 번 실패한 후부터 금식 기도를 안 하고 있었다. 어려운 일이긴 하나 다시 금식 기도를 시작해야 겠다. 종일 금식은 육아 때문에 힘들더라도 한 끼 금식이라도 해야겠다. 하나님을 경외하여 하늘 양식이 귀함을 온전히 누리고 싶다. 
- 그리고 허락하신다면 성령님의 능력으로 영을 분별하여 복음을 전하고 복음 전파를 막는 마귀를 주목하여 보고 대적하며 살고 싶다. 

10. 영적터치(단어/구절) 
9 바울이라고 하는 사울이 성령이 충만하여 그를 주목하고

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-03', '사도행전', '13장 11절 ~ 20절', '현 시대에도 이어져야 할 복음', '[행13:11-20]
11 보라 이제 주의 손이 네 위에 있으니 네가 맹인이 되어 얼마 동안 해를 보지 못하리라 하니 즉시 안개와 어둠이 그를 덮어 인도할 사람을 두루 구하는지라
12 이에 총독이 그렇게 된 것을 보고 믿으며 주의 가르치심을 놀랍게 여기니라
13 바울과 및 동행하는 사람들이 바보에서 배 타고 밤빌리아에 있는 버가에 이르니 요한은 그들에게서 떠나 예루살렘으로 돌아가고
14 그들은 버가에서 더 나아가 비시디아 안디옥에 이르러 안식일에 회당에 들어가 앉으니라
15 율법과 선지자의 글을 읽은 후에 회당장들이 사람을 보내어 물어 이르되 형제들아 만일 백성을 권할 말이 있거든 말하라 하니
16 바울이 일어나 손짓하며 말하되 이스라엘 사람들과 및 하나님을 경외하는 사람들아 들으라
17 이 이스라엘 백성의 하나님이 우리 조상들을 택하시고 애굽 땅에서 나그네 된 그 백성을 높여 큰 권능으로 인도하여 내사
18 광야에서 약 사십 년간 그들의 소행을 참으시고
