4. 주제 만들기
주제: 바울과 바나바를 통해 넓게 퍼져나가는 복음 

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 여러 지역을 다니며 제자를 세우고 다른 지역에서 복음을 전하다가 다시 세운 제자들을 찾아가 믿음을 견고하게 하는 바울과 바나바
- 장로들을 택하여 금식 기도하며 하나님께 그들을 위탁하는 두 사도
- 안디옥 교회에서 하나님이 함께 행하신 모든 일과 이방인들에게 믿음의 문을 여신 것을 보고하는 두 사도
- 제자들과 오래 있는 두 사도

7.하나님 찾기(해석)

8. 인간(해석)
- 복음을 전하는 것과 제자들의 믿음을 견고하게 하는 것과 장로를 세우고 교회를 맡기는 일을 자신의 힘과 능력으로 하지 않고 하나님께 의탁하는 두 사도
- 안디옥 교회로 돌아와 선교 기간동안 동행하신 하나님의 도우심과 능력에 대해 이야기 하며 기뻐하고 하나님의 말씀이 다른 지역으로 넓게 확산되는 것을 보고 하며 기쁨이 넘쳤을 것이다. 
- 하나님의 역사하심을 경험한 기쁨을 나누며 교제하고, 성도의 교제를 누리며 기뻐했을 것이다.

9. 적용(나)
- 모세와 여호수아 이야기를 보면 이방인을 정복해 나가는 이스라엘 이야기가 나온다. 복음이 지역마다 전파되는 이야기를 볼 때면 모세와 여호수아의 이야기가 떠오른다. 복음이 전파 되는 것은 구약의 이스라엘이 가나안으로 나아갈 때 있었던 전투와 같다고 생각한다. 전투는 우리의 능력에 있지 않다. 우리는 미련한 자인데 복음을 전파할 마음과 여건을 주신 것은 하나님이다. 우리는 전파하고 역사하신 하나님을 자랑하면 그만이다.
- 나를 보내신 곳에서 성경적 삶을 살아내며 그리스도의 편지로 읽히고, 편지를 읽은 그들과 대화하며 내게 역사하신 하나님을 나누고, 복음을 나누는 삶을 살아야 한다.(사실 교회에 다니는 사람들도 복음을 모르는 이가 많다.)
- 나아가 마포대교, 인근 학교, 마을들을 다니며 복음을 전해야 한다. 
- 믿는 이들이 모여 하나님의 역사하심을 이야기하며 기뻐하고, 그곳에서 교제하며 기쁨을 누리고 힘을 얻어야 한다.
 
10. 영적터치(단어/구절)
27 하나님이 함께 행하신 모든 일과 이방인들에게 믿음의 문을 여신 것

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-10', '사도행전', '15장 1절 ~ 10절', '할례보다 중요한건 율법을 깨뜨리신 예수님의 복음과 구원', '[행15:1-10]
1 어떤 사람들이 유대로부터 내려와서 형제들을 가르치되 너희가 모세의 법대로 할례를 받지 아니하면 능히 구원을 받지 못하리라 하니
2 바울 및 바나바와 그들 사이에 적지 아니한 다툼과 변론이 일어난지라 형제들이 이 문제에 대하여 바울과 바나바와 및 그 중의 몇 사람을 예루살렘에 있는 사도와 장로들에게 보내기로 작정하니라
3 그들이 교회의 전송을 받고 베니게와 사마리아로 다니며 이방인들이 주께 돌아온 일을 말하여 형제들을 다 크게 기쁘게 하더라
4 예루살렘에 이르러 교회와 사도와 장로들에게 영접을 받고 하나님이 자기들과 함께 계셔 행하신 모든 일을 말하매
5 바리새파 중에 어떤 믿는 사람들이 일어나 말하되 이방인에게 할례를 행하고 모세의 율법을 지키라 명하는 것이 마땅하다 하니라
6 사도와 장로들이 이 일을 의논하러 모여
7 많은 변론이 있은 후에 베드로가 일어나 말하되 형제들아 너희도 알거니와 하나님이 이방인들로 내 입에서 복음의 말씀을 들어 믿게 하시려고 오래 전부터 너희 가운데서 나를 택하시고
8 또 마음을 아시는 하나님이 우리에게와 같이 그들에게도 성령을 주어 증언하시고
9 믿음으로 그들의 마음을 깨끗이 하사 그들이나 우리나 차별하지 아니하셨느니라
10 그런데 지금 너희가 어찌하여 하나님을 시험하여 우리 조상과 우리도 능히 메지 못하던 멍에를 제자들의 목에 두려느냐

