3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 7월25일 사도행전 15장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-모세의 법(1,5절), 할례(1,5절), 변론(2,7절), 사도(2,4,6절), 장로(2,4,6절), 이방인(3,5,7절)
4.주제만들기 : 할례보다 중요한건 율법을 깨뜨리신 예수님의 복음과 구원
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
-모세의 법대로 행하지 않으면 구원을 받지 못한다고 주장하는 일부 유대인들
-다툼과 변론이 있어 바울과 바나바를 예루살렘이 있는 사도와 장로들에게 보냄
-이 일에 대해 의논함
-여전히 바리새파인 중에서 이방인도 할례를 강조하고 모세의 율법을 지켜야 한다고 주장함
-베드로는 이방인들에게 동일한 성령을 주었고 차별하지 않아야한다고 강조하며 무거운 짐을 이방인들에게 주어 하나님을 시험하려하냐고 말함.
7.하나님 찾기 (해석) 
8.인간(해석):
- 우리는 가끔 형식과 절차의 오류에 빠질 때가 있다. 당시 제자들도 마찬가지였을 것이다. 예수님께서 멍에를 대신 짊어지셔서 자유케하셨는데 형식과 절차의 오류에서 빠져 나오지 못하고 있는 사도와 제자들이 있었다.
- 베드로는 할례가 중요한 것이 아니니 이방인들에게 짐을 주어서는 안 된다고 말한다. 하나님을 시험하지 말라고 강하게 말한다. 베드로가 지혜로운 판단을 한 것이 놀랍다. 은혜가 충만하면 하나님께서 원하시는 것이 무엇인지 분별할 수 있다.
9. 적용(나): 
- 나도 형식과 절차를 중요시 여기는 성격이라 오류에 빠질 수 있는 상황이 너무 많다. 예민한 성격으로 공동체에게 어려움을 줄 때도 있다. 내 생각이 입으로 나가기 전에 기도를 하고 성령님의 음성을 들어보는 훈련이 필요하다. 
- 우리 팀에 들어오는 새로운 회원에게 나의 기준으로 이 정도는 해야되지 않나라고 생각을 할 때가 많았는데 새로운 회원이 적응할 수 있도록 넓은 마음을 바라보아야 했음을 깨닫는다.  
- 누구든지 차별하지 않는 습관을 가져야겠다. 의지적인 노력과 훈련이 필요하다.
10. 영적터치(단어/구절) : 차별
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-11', '사도행전', '15장 11절 ~ 20절', '이방인들로 자기 이름을 위할 백성을 취하시려…', '11. 그러나 우리는 그들이 우리와 동일하게 주 예수의 은혜로 구원 받는 줄을 믿노라 하니라
12. 온 무리가 가만히 있어 바나바와 바울이 하나님께서 자기들로 말미암아 이방인 중에서 행하신 표적과 기사에 관하여 말하는 것을 듣더니 
13. 말을 마치매 야고보가 대답하여 이르되 형제들아 내 말을 들으라
14. 하나님이 처음으로 이방인 중에서 자기 이름을 위할 백성을 취하시려고 그들을 돌보신 것을 시므온이 말하였으니
15. 선지자들의 말씀이 이와 일치하도다 기록된바
16. 이 후에 내가 돌아와서 다윗의 무너진 장막을 다시 지으며 또 그 허물어진 것을 다시 지어 일으키리니
17. 이는 그 남은 사람들과 내 이름으로 일컬음을 받는 모든 이방인들로 주를 찾게 하려 함이라 하셨으니
18. 즉 예로부터 이것을 알게 하시는 주의 말씀이라 함과 같으니라
19. 그러므로 내 의견에는 이방인 중에서 하나님께로 돌아오는 자들을 괴롭게 하지 말고 
20. 다만 우상의 더러운 것과 음행과 목매어 죽인 것과 피를 멀리하라고 편지하는 것이 옳으니

