-주 예수의 은혜로 구원 받는다고 말함
-모든 이방인들로 주를 찾게 하려 한다고 말함
-하나님께로 돌아오는 자들은 그 누구이건 괴롭히지 말고 다만 우상과 더러운 것으로부터 멀리하라고 선포함
7.하나님 찾기 (해석) 
8.인간(해석):
-오늘날 안 믿는 사람들이 기독교는 이스라엘의 종교 아니냐, 그런데 왜 우리 한국 사람들이 동양의 샤머니즘이나 불교를 믿지 않고 서양 종교를 믿느냐, 그 서양 종교를 믿고 어떻게 구원을 받느냐는 질문을 많이 한다. 하지만 성경에서는 분명히 이방인인 우리가 주 예수 그리스도의 은혜로 말미암아 구원을 받는다고 분명히 말하고 있다.
-가끔 나 또한 이런 질문으로 믿음의 뿌리가 흔들릴 때가 있다. 하지만 이것은 마귀가 얕은 잔꾀로 나의 믿음을 흔들고 하나님으로부터 멀리하려는 전략임을 간파하고 더욱 주님을 찾고 기도하며 말씀으로 물리치곤 한다. 더더욱 말씀과 기도로 주님을 의지하고 무릇 지킬만한 것중에 내 마음을 더 지키며 생각을 지키고 생명의 말씀을 가까이 해야겠다.
