1:감동받는 단어나 구절 찾기(영적터치)

2023년 7월 27일 사도행전 15장 21~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)


4. 주제 만들기
주제: 복음의 불순물을 제거하는 제자들 

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 교회 가운데서 어떤 사람들이 공회의 지시도 없이 나가서 말(이방인과 할례에 관한)로 이방인과 안디옥 교회를 괴롭게 하고 마음을 혼란하게 함.
- 유다와 실라를 택하여 바울과 바나바와 함께 안디옥으로 보내기를 결정한 공회
- 이방인에게 할례를 받지 않아도 구원받을 수 있음을 알리되, 우상의 제물과 피와 목매어 죽인 것과 음행을 멀리할 것을 말하는 공회
- 위의 네 가지를 스스로 삼가면 잘되리라 말하고, 이방인을 포함한 교회의 평안함을 원한다고 말하는 공회

7.하나님 찾기(해석)

8. 인간(해석)
- 베드로를 포함한 예루살렘 공회는 구원의 문제에 있어서 이방인도 예수님을 믿으면 구원받는 것을 말하고 할례는 구원과 상관이 없음을 정확히 함.
- 예수님을 믿음으로 구원을 받는 것이 진리이기 때문에 이방인은 안 된다거나 할례를 받아야만 구원받는다는 등의 불순물이 끼는 것은 잘못된 것임을 명확히 하는 공회 
- 하나님이 사랑하시는 이방인과 교회의 평안함을 원하는 공회

9. 적용(나)
- 예수님을 통해 하나님의 사랑을 더 알게 된 제자들은 하나님의 사랑이 이방인을 포함한 모든 세상에 미친다는 것을 알고 기뻐했다. 
- 그리고 여기서 멈추지 않고 복음에 대해 잘못 이야기하는 것을 그냥 보고 있지 않았다. 
- 첫째는 복음이 하나님의 뜻대로 전해지길 원했기 때문이고,
- 둘째는 잘못된 복음과 구원관으로 인해 이방인을 포함한 교회 구성원이 혼란을 겪거나 심중에 괴로움을 느끼는 것은 원치 않았기 때문일 것이다.
- 오늘날에도 복음에 대해 모르고 있는 교인들과 잘못 알고 있는 교인들이 많다. 교인이 아닌 사람은 더 그렇다.
- 내게 복음을 묻는 사람들에게 시간을 내어 복음을 정확히 전하고, 교회에서도 1년에 한 번씩 시간을 내어 복음을 심도 있게 전해야한다.  
 
10. 영적터치(단어/구절)
29 평안함을 원하노라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-13', '사도행전', '15장 31절 ~ 41절', '원칙보다 중요한 예수님의 사랑', '[행15:31-41]
31 읽고 그 위로한 말을 기뻐하더라
32 유다와 실라도 선지자라 여러 말로 형제를 권면하여 굳게 하고
33 얼마 있다가 평안히 가라는 전송을 형제들에게 받고 자기를 보내던 사람들에게로 돌아가되
[34] 
35 바울과 바나바는 안디옥에서 유하며 수다한 다른 사람들과 함께 주의 말씀을 가르치며 전파하니라
36 며칠 후에 바울이 바나바더러 말하되 우리가 주의 말씀을 전한 각 성으로 다시 가서 형제들이 어떠한가 방문하자 하고
37 바나바는 마가라 하는 요한도 데리고 가고자 하나
38 바울은 밤빌리아에서 자기들을 떠나 함께 일하러 가지 아니한 자를 데리고 가는 것이 옳지 않다 하여
39 서로 심히 다투어 피차 갈라서니 바나바는 마가를 데리고 배 타고 구브로로 가고
40 바울은 실라를 택한 후에 형제들에게 주의 은혜에 부탁함을 받고 떠나
