- 바울과 바나바는 복음 전파라는 동일한 목적을 가지고 그 일에 힘썼다. 그러나 바울과 바나바처럼 목숨을 바치며 사역하는 것이 함께하는 동료에겐 동기부여가 되는 반면 누군가에게는 버거움으로 다가올 수 있다. 마가가 그랬던 것 같다. 
9. 적용(나): 
