- 예수님께서 하신것처럼 동일한 기준으로 우리를 바라보셨다면 우리는 예수님께 엄청난 꾸지람을 들을 것이다. 그런데 예수님은 그러지 않으시고 늘 우리에게 용기와 희망을 주신다. 
- 바울이 변화되고 주의 일을 하는데 집중했지만 마가를 사랑으로 감싸지 못했다. 바울의 입장에서 충분히 이해가 되는 부분이기도 하다. 하지만 예수님은 사랑을 원하신다. 끝까지 사랑하라고 하신다. 나 또한 사랑으로 대해야 할 성도들과 회원들이 떠오른다. 사랑해야 됨을 알면서도 미워하는 마음을 누르지 못한다. 간절히 기도해야겠다. 예수님의 마음으로 사랑하도록.
