바울은 소아시아로 가서 복음을 증거할 계획을 가지고 있었지만 그것을 성령하나님은 막으시고 환상을 통하여 바울의 선교방향을 마게도냐로 이끄셨다. 바울은 하나님의 뜻인것을 받아들이고 곧장 마게도냐로 향한다. 성령하나님의 음성에 민감하고 순종하는 바울의 모습을 볼수있다. 자신이 행하고자하는 일이  커 보여도 주님의 뜻이 아니라면 과감하게 포기하는 용기또한 하나님의 자녀의 모습인것을 보여진다.

