7.하나님 찾기(해석)
주님은 마게도냐에 속한 빌립보성안에 사는 자색 옷감 장사 루디아의 마음을 열어 바울이 전하는 복음을 믿게 마음문을 여신다. 주님을 믿고 순종하며 따르는 자들은 준비된 영혼을 만나는 기쁨을 주님의 은혜가운데 체험한다.
8. 인간 찾기(해석)
귀신들린 여종을 이용하여 부를 축척하는 악덕주인들이 있는 반면에 한 영혼을 귀히 여기어 귀신을 쫒아내므로 대조를 이루는 바울의 모습을 볼수있다. 이 일로 주인으로부터 미움을 받고 관리들에게 잡혀 끌려가는 고초를 당한다. 복음을 전하다보면 루디아 케이스같이 쉽게 진행되는 경우 도 있고 도리어 신변에 위협을 받는 경우도 생긴다.

9. 적용(나)
자신의 불이익 을 감수하더라도 한영혼을위하여 귀신을 쫒아주는 바울의 모습을 본다. 나도 주님께 받은 여러가지 은사들을  영혼구원을 위하여 순수한 동기로 사용해야겠다
