- 

8.인간(해석): 
- 고난과 고통에 상관없이 하나님께 기도하고 찬송하는 바울과 실라. 하나님의 위대하심을 깊이 알기 때문이며, 예수님의 남은 고난에 동참할 수 있음에 감사했기 때문이며, 헐 벗김과 매 맞음과 깊은 옥에 갖힐 만한 자로 인정받음에 기뻤을 것이다. 그리고 어쩌면 기도하는 중에 옥에서 나가게 될 것과 복음을 계속 전하게 될 것임을 성령님께서 깨닫게 하셨을 수도 있을 것이다.
- 바울과 실라가 옥에 갖혀 기도하고 찬송하는 소리를 들은 죄수들은 이들의 능력이 어디서 나오는지 궁금했을 것이며 그런 모습에 놀라움을 감추지 못했을 것이다. 바울과 실라가 무슨 일로 갖혔는지 들었다면, 그들의 능력이 예수님으로부터 나왔다는 것을 느꼈을 것이다.
- 크게 소리 질러 간수의 죽음을 막는 바울을 보면 한 사람의 생명을 얼마나 귀하게 여겼는지 알 수 있다. 
- 바울과 실라의 기도와 찬송을 간수도 들었는지는 모르겠으나 옥문이 열렸음에도 죄수들이 도망하지 않은 것을 보고 간수는 충격을 받았을 것이다. 고통과 죽음에 대한 두려움조차도 초월한 바울과 실라의 모습을 보며 그들이 전하는 예수님의 능력이 대체 무엇인지 궁금했을 것이다. 

9. 적용(나): 
- 비전을 향해 나아가면서 약간의 고난과 고통만 있어도 인간의 방법으로 해결하려 하거나 남에게 고통을 주기도 하는 내 모습이 떠오른다. 옷이 찟기고 매를 맞고 옥에 갖혀도 기도하고 찬송한 바울의 모습을 본받아야 한다.
- 자신을 옥에 가둔 간수의 생명을 귀히 여기는 바울의 모습을 본받아야 한다.

10. 영적터치(단어/구절) 
28 바울이 크게 소리 질러 이르되 네 몸을 상하지 말라 우리가 다 여기 있노라 하니 

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

