8.인간(해석):
- 간수는 구원 받는 것이 중요함을 깨닫고 바울과 실라에게 요청하여 복음을 받아들였다. 그리고 위험이 있음에도 불구하고 자신의 집으로 데려가 상처를 치료하고 음식을 대접했으며 온 가족이 복음을 받아들였다. 그리고 복음에 대해 기뻐했다.
- 반면 상관들은 바울과 실라를 조용히 감옥에서 내보내고자 했다. 그러나 로마 사람이라는 사실을 알고 감옥에 찾아와 나가달라고 정중히 요청한다. 
9. 적용(나): 
- 하나님을 믿는 것이 당연한 것처럼 은혜에 감사함과 소중함을 잊어버릴 때가 너무 많다. 지금 어디선가 목숨걸고 예수님을 전하고 믿고 있는 분들이 계실텐데 한없이 부끄러워진다. 
- 노방전도를 처음 해봤는데 엄청 기쁘진 않았다. 반대편에서 마주하는 사람들이 없었으면 하는 바램이 있었기 때문이다. 아직 내 자아가 더 커서 복음을 전하는데 불편함이 있다. “그런즉 이제는 내가 사는 것이 아니요 오직 내 안에 그리스도께서 사시는 것이라. 이제 내가 육체 가운데 사는 것은 나를 사랑하사 나를 위하여 자기 자신을 버리신 하나님의 아들을 믿는 믿은 안에서 사는 것이라”말씀처럼 자기 자신을 버리신 예수님처럼 나 스스로를 버리는 훈련이 지속되어야겠다.
