1:감동받는 단어나 구절 찾기(영적터치)

2023년 8월4일 사도행전 17장 21절~34절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천) 
- 알지 못하는(23절), 소생(28절, 29절), 죽은자(31, 32절), 어떤 사람은(32절)
4.주제만들기 : 영혼 구원을 위해 기쁜 마음으로 감내해야할 수 있는 조롱
5.하나님 찾기 (관찰)
-만물을 지으신 하나님
-인간의 손으로 섬김을 받지 아니하시고 만민의 생명과 호흡과, 만물을 친히 주시는 분
-인류의 모든 족속을 한 혈통으로 만드시고 온 땅에 살게하시고 연대를 정하시며 거주의 경계를 한정하심,
-하나님께선 우리 각 사람에게서 멀리 계시지 않음
6.인간 찾기 (관찰)
-바울이 아레오바고 광장 가운데 서서 복음을 전함
-다시 살아난다는 말에 비웃은 사람들이 있는 반면 그 이야기를 다시 듣고 싶다며 몇몇 사람은 하나님을 믿게 됨
7.하나님 찾기 (해석) 
8.인간(해석):
-바울은 아테네에서 많은 신을 만들고 알지 못하는 신까지 만드는 종교심을 이용해 복음을 전한다. 그러나 다시 살아난다는 말에 대부분의 사람들이 바울의 말을 믿지 않는다. 이성적인 생각이 강했던 자들에겐 하나님의 은혜가 임하지 못했다. 반면 하나님을 궁금해하는 몇몇 사람에겐 하나님의 은혜로 믿음을 갖게 되었다. 
9. 적용(나): 
-복음을 전하는 일은 험난한 일이다. 이성적인 머리론 하나님을 인정할 수 없으니 그들의 눈엔 그리스도를 전하는 사람들이 한심스러울 것이다. 그런데 복음을 전하는 사람들은 조롱을 받으면서 그들을 섭섭해하지 않고 안타까워한다. 하나님의 은혜가 아니면 긍휼한 마음이 생길 수가 없다. 
-노방전도를 할 때 사영리를 받지 않는 사람들을 위해 짧게나마 기도를 해야겠다. 우리나라에 교회는 많지만 믿음이 없거나 믿지 않는 사람들이 점점 늘어나고 있다. 너무 안타까운 현실이다. 교회가 다시 선한 영향력을 보일 수 있도록 나부터 변화되길 기도한다.  
10. 영적터치(단어/구절) : 몇 사람이 그를 가까이하여 믿으니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-21', '사도행전', '18장 1절 ~ 10절', '제목 없음', '(사도행전 18장)
1.  그 후에 바울이 아덴을 떠나 고린도에 이르러
2. 아굴라라 하는 본도에서 난 유대인 한 사람을 만나니 글라우디오가 모든 유대인을 명하여 로마에서 떠나라 한 고로 그가 그 아내 브리스길라와 함께 이달리야로부터 새로 온지라 바울이 그들에게 가매
3. 생업이 같으므로 함께 살며 일을 하니 그 생업은 천막을 만드는 것이더라
4. 안식일마다 바울이 회당에서 강론하고 유대인과 헬라인을 권면하니라
5. 실라와 디모데가 마게도냐로부터 내려오매 바울이 하나님의 말씀에 붙잡혀 유대인들에게 예수는 그리스도라 밝히 증언하니
6. 그들이 대적하여 비방하거늘 바울이 옷을 털면서 이르되 너희 피가 너희 머리로 돌아갈 것이요 나는 깨끗하니라 이 후에는 이방인에게로 가리라 하고
7. 거기서 옮겨 하나님을 경외하는 디도 유스도라 하는 사람의 집에 들어가니 그 집은 회당 옆이라
8. 또 회당장 그리스보가 온 집안과 더불어 주를 믿으며 수많은 고린도 사람도 듣고 믿어 세례를 받더라
9. 밤에 주께서 환상 가운데 바울에게 말씀하시되 두려워하지 말며 침묵하지 말고 말하라
10. 내가 너와 함께 있으매 어떤 사람도 너를 대적하여 해롭게 할 자가 없을 것이니 이는 이 성중에 내 백성이 많음이라 하시더라

