INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-23', '사도행전', '18장 21절 ~ 28절', '제자를 굳건하게 하는 바울, 아볼로를 발견하고 가르친 브리스길라와 아굴라', '[행18:21-28]
21 작별하여 이르되 만일 하나님의 뜻이면 너희에게 돌아오리라 하고 배를 타고 에베소를 떠나
22 가이사랴에 상륙하여 올라가 교회의 안부를 물은 후에 안디옥으로 내려가서
23 얼마 있다가 떠나 갈라디아와 브루기아 땅을 차례로 다니며 모든 제자를 굳건하게 하니라
24 알렉산드리아에서 난 아볼로라 하는 유대인이 에베소에 이르니 이 사람은 언변이 좋고 성경에 능통한 자라
25 그가 일찍이 주의 도를 배워 열심으로 예수에 관한 것을 자세히 말하며 가르치나 요한의 세례만 알 따름이라
26 그가 회당에서 담대히 말하기 시작하거늘 브리스길라와 아굴라가 듣고 데려다가 하나님의 도를 더 정확하게 풀어 이르더라
27 아볼로가 아가야로 건너가고자 함으로 형제들이 그를 격려하며 제자들에게 편지를 써 영접하라 하였더니 그가 가매 은혜로 말미암아 믿은 자들에게 많은 유익을 주니
28 이는 성경으로써 예수는 그리스도라고 증언하여 공중 앞에서 힘있게 유대인의 말을 이김이러라

 

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 8월7일 사도행전 18장 21절~28절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하나님: 21, 26
에베소: 21, 24
아볼로: 24, 27
성경: 24, 28
유대인: 24, 28
예수: 25, 28

4.주제만들기: 제자를 굳건하게 하는 바울, 아볼로를 발견하고 가르친 브리스길라와 아굴라

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
세운 교회들을 순회하며 믿음을 굳거하게 하는 바울
에베소에 온 아볼로
아볼로에게 복음을 더 정확하게 가르치는 브리스길라와 아굴라
아가야로 가서 믿은 자들에게 많은 유익을 주는 아볼로
성경으로써 예수는 그리스도라고 증언하여 유대인의 말을 이긴 아볼로

7.하나님 찾기 (해석) 

8.인간(해석): 
- 아가야에서 핍박 받아 심신이 많이 지쳤음에도 불구하고 열심을 내어 세운 교회를 찾아가고 말씀을 선포함으로 믿음을 견고하게 한 바울. 주님께 어느 정도까지 충성했는지 볼 수 있다. ‘맡은 자들에게 구할 것은 충성이니라.’ 고전 4:2
- 아볼로를 알아보고 복음을 더 정확하게 가르친 것을 보면 브리스길라와 아굴라는 성령 충만하여 보는 눈이 있었고 말씀에도 능통했다.
- 브리스길라와 아굴라를 통해 복음에 대해 더 정확하게 배운 아굴라는 성령이 충만하게 되고 기쁨이 넘쳤을 것이다. 이에 바울이 쫓겨난 아가야로 갈 용기를 더 얻었을 것이고, 그동안 쌓은 성경 지식과 언변, 그리고 성령 충만함으로 아가야 유대인의 말을 이겼을 것이다. 

9. 적용(나): 
- 바울처럼 피로와 고난을 이겨내고 예수님께 충성된 삶을 살아내야 한다. 지금 나는 너무나 나약하다.
- 성경에 능통한 아볼로의 말에 부족한 것을 알아챈 브리스길라와 아굴라처럼 말씀을 정확하게 알고 있어야 한다. 날마다 성경을 상고하여 말씀을 바르게 전하는 자가 되도록 힘써야 한다.
- 아볼로의 성경 지식과 용기를 배워야 한다. 바울과 같은 사람이 쫓겨난 곳도 도전할 수 있는 용기와 근성이 필요하다. 
  성경으로 풀어서 예수님을 전하는 능력은 믿는 자들에게도 감동을 주지만, 믿지 않는 자들에게도 힘이 있을 것이다. 

10. 영적터치(단어/구절)  
26 하나님의 도를 더 정확하게 풀어 이르더라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-24', '사도행전', '19장 1절 ~ 10절', '꾸준히 이루어가야할 복음 전파', '[행19:1-10]
1 아볼로가 고린도에 있을 때에 바울이 윗지방으로 다녀 에베소에 와서 어떤 제자들을 만나
2 이르되 너희가 믿을 때에 성령을 받았느냐 이르되 아니라 우리는 성령이 계심도 듣지 못하였노라
3 바울이 이르되 그러면 너희가 무슨 세례를 받았느냐 대답하되 요한의 세례니라
4 바울이 이르되 요한이 회개의 세례를 베풀며 백성에게 말하되 내 뒤에 오시는 이를 믿으라 하였으니 이는 곧 예수라 하거늘
5 그들이 듣고 주 예수의 이름으로 세례를 받으니
6 바울이 그들에게 안수하매 성령이 그들에게 임하시므로 방언도 하고 예언도 하니
7 모두 열두 사람쯤 되니라
8 바울이 회당에 들어가 석 달 동안 담대히 하나님 나라에 관하여 강론하며 권면하되
9 어떤 사람들은 마음이 굳어 순종하지 않고 무리 앞에서 이 도를 비방하거늘 바울이 그들을 떠나 제자들을 따로 세우고 두란노 서원에서 날마다 강론하니라
10 두 해 동안 이같이 하니 아시아에 사는 자는 유대인이나 헬라인이나 다 주의 말씀을 듣더라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 8월8일 사도행전 0장 0절~0절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 성령(2,6절), 세례(3,4,5절), 예수(4,5절), 강론(8,9절)
4.주제만들기 : 꾸준히 이루어가야할 복음 전파
5.하나님 찾기 (관찰)
- 성령이 제자들에게 임하심
6.인간 찾기 (관찰)
- 바울은 어떤 제자들을 만나 성령을 받았는지 물으며 요한의 세례에 대한 의미와 예수님에 대해 알려주며 예수님의 이름으로 세례를 베품
- 어떤 제자들은 그 말을 듣고 세례를 받자 성령이 임했고 방언과 예언을 하게 됨
- 바울은 회당에 들어가 담대히 하나님의 말씀을 강론하고 권면함
- 마음이 굳어 순종하지 않고 무리 앞에서 비방하자 바울은 제자들을 따로 세워 두란노 서원에서 강론함
- 두해 동안 이같이 하자 아시아에 사는 유대인이나 헬라인들이 주님의 말씀을 듣게 됨
7.하나님 찾기 (해석 ) 8.인간(해석):
-복음 전파에 대한 열망은 그의 행동에서 나타나는데 누구를 만나든 예수님을 전했고 예수님을 믿고자 하면 예수님의 이름으로 세례를 베풀었다. 또한 석달동안 담대히 하나님의 말씀을 전하는 동안 마음이 굳은 자들의 비방도 감수 했다. 그 후 따로 제자들을 세워 하나님의 말씀을 강론했고 두해에 걸쳐 하나님을 전하자 아시아 지역에서 유대인과 헬라인 모두 하나님의 말씀을 듣게 되었다. 
9. 적용(나): 
- 사도 바울은 예수님을 전하는 일과 함께 하나님의 말씀을 강론하는 일에도 많은 노력을 기울였음을 알게된다. 그것은 예수님을 믿더라도 성경을 잘못 알거나 성경을 잘못 해석하거나 무지하면 시험에 들거나 무너질 수 있는 일들이 많음을 사도 바울은 알았을 것이다. 
- 전도하는 일 + 예수님을 잘 알고, 예수님의 뜻을 따라 살아가기 위한 노력을 지속적으로 해야겠다.   
10. 영적터치(단어/구절) : 두해동안 이같이 하니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-25', '사도행전', '19장 11절 ~ 20절', '제목 없음', '(사도행전 19장)
11. 하나님이 바울의 손으로 놀라운 능력을 행하게 하시니
12. 심지어 사람들이 바울의 몸에서 손수건이나 앞치마를 가져다가 병든 사람에게 얹으면 그 병이 떠나고 악귀도 나가더라
13. 이에 돌아다니며 마술하는 어떤 유대인들이 시험삼아 악귀 들린 자들에게 주 예수의 이름을 불러 말하되 내가 바울이 전파하는 예수를 의지하여 너희에게 명하노라 하더라
14. 유대의 한 제사장 스게와의 일곱 아들도 이 일을 행하더니
15. 악귀가 대답하여 이르되 내가 예수도 알고 바울도 알거니와 너희는 누구냐 하며
16. 악귀 들린 사람이 그들에게 뛰어올라 눌러 이기니 그들이 상하여 벗은 몸으로 그 집에서 도망하는지라
17. 에베소에 사는 유대인과 헬라인들이 다 이 일을 알고 두려워하며 주 예수의 이름을 높이고
18. 믿은 사람들이 많이 와서 자복하여 행한 일을 알리며
19. 또 마술을 행하던 많은 사람이 그 책을 모아 가지고 와서 모든 사람 앞에서 불사르니 그 책 값을 계산한즉 은 오만이나 되더라
20. 이와 같이 주의 말씀이 힘이 있어 흥왕하여 세력을 얻으니라

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)
2023년 8월09일 사도행전 19장11절~20절

1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기
악귀: 12절 13절 15절 16절
마술하는 사람: 13절 19절
능력: 11절 12절  17절20절
예수: 13절(2) 15절 17절
바울: 11절 12절 15절

4. 주제 만들기
모든 능력은 하나님께로 부터

5.하나님 찾기(관찰)
하나님은 바울의 손으로 놀라운 능력을 행하심

6.인간 찾기(관찰)
바울의 앞치마나 손수건을 이용해서 능력을 행하는 샤람들
제사장 스게와의 일곱 아들은 악귀한테 쫒김을 당하고 도망감
마술사를 포함하여 많은 사람들이 주님께 돌아옴

7.하나님 찾기(해석)
은밀한 가운데 바울에게 능력을 주신 하나님

8. 인간 찾기 (해석)
사악한 악귀도 사도바울을 알아볼정도로 바울이 얼마나 주님앞에서신실한 사람 이었는가를 알수있다. 반면에 제사장 일곱 아들은 예수이름으로 악귀를 쫓아보려고 했지만 도리어 몸이 상하여 도망가는 수모를 당했다. 진정한 능력은 믿음을 가지고 예수님의 이름을 부르는 자에게 주어지는 특권이다.

9. 적용(나)
모든 능력은 하나님으로부터 온것임을 굳게믿고 행하는 복음의 일꾼이 되야겠다.
10. 영적터치(단어/구절)
 11절: 하나님이 바울의 손으로 놀라운 능력을 행하게 하시니

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-26', '사도행전', '19장 21절 ~ 30절', '바울을 핍박하기 위해 아데미와 관련된 일을 하는 자들을 격동하는 데메드리오&nbsp;', '(사도행전 19장)
21 이 일이 있은 후에 바울이 마게도냐와 아가야를 거쳐 예루살렘에 가기로 작정하여 이르되 내가 거기 갔다가 후에 로마도 보아야 하리라 하고
22 자기를 돕는 사람 중에서 디모데와 에라스도 두 사람을 마게도냐로 보내고 자기는 아시아에 얼마 동안 더 있으니라
23 그 때쯤 되어 이 도로 말미암아 적지 않은 소동이 있었으니
24 즉 데메드리오라 하는 어떤 은장색이 은으로 아데미의 신상 모형을 만들어 직공들에게 적지 않은 벌이를 하게 하더니
25 그가 그 직공들과 그러한 영업하는 자들을 모아 이르되 여러분도 알거니와 우리의 풍족한 생활이 이 생업에 있는데
26 이 바울이 에베소뿐 아니라 거의 전 아시아를 통하여 수많은 사람을 권유하여 말하되 사람의 손으로 만든 것들은 신이 아니라 하니 이는 그대들도 보고 들은 것이라
27 우리의 이 영업이 천하여질 위험이 있을 뿐 아니라 큰 여신 아데미의 신전도 무시 당하게 되고 온 아시아와 천하가 위하는 그의 위엄도 떨어질까 하노라 하더라
28 그들이 이 말을 듣고 분노가 가득하여 외쳐 이르되 크다 에베소 사람의 아데미여 하니
29 온 시내가 요란하여 바울과 같이 다니는 마게도냐 사람 가이오와 아리스다고를 붙들어 일제히 연극장으로 달려 들어가는지라
30 바울이 백성 가운데로 들어가고자 하나 제자들이 말리고

