4.주제만들기: 바울을 핍박하기 위해 아데미와 관련된 일을 하는 자들을 격동하는 데메드리오 

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 디모데와 에라스도 두 사람을 마게도냐로 보내고 아시아에 머문 바울
- 아데미 신상 직공들과 그러한 영업하는 자들을 모아 격동시키는 데메드리오
- 데메드리오의 말을 듣고 분노가 가득하여 외치는 사람들
- 가이오와 아리스다고를 붙들어 일제히 연극장으로 달려 들어가는 사람들
- 연극장으로 가려는 바울과 그를 말리는 제자들

7.하나님 찾기 (해석) 

8.인간(해석): 
- 바울과 제자들에 의해 에베소를 포함한 아시아에 믿는 자들이 많이 생겼을 것이다. 이에 아데미 관련 상업이 쇠퇴했을 것이고 이것으로 돈을 많이 벌던 데메드리오의 수입은 많이 줄었을 것이다. 수입을 회복하고 싶었던 데메드리오는 같은 일을 하는 사람들을 모아 선동했고 이것은 성공했다.
- 아데미 신상과 관련된 일을 하던 많은 사람들은 큰 소리로 외치며 가이오와 아리스다고를 붙잡아 연극장으로 달려 들어갔다. 가이오와 아리스다고를 붙잡은 사람들은 무력을 행사하여 복음이 전해지는 것을 막고 싶었을 것이다. 복음 전파가 멈춰지고 교회가 주춤해야 아데미 신상 관련된 일들이 다시 인정받고 장사가 잘 될 것이기 때문이다.
- 가이오와 아리스다고를 구하고, 연극장에 모인 사람들과 변론하고 싶었을 바울. 그런 바울이 잡혀 죽을 것 같아 막는 제자들. 

9. 적용(나): 
- 복음이 전파되는 것이 세상(멸망하는) 사람들에게는 미련한 것이다. 나아가 복음 전파로 인해 세상의 이익이 줄어들거나 그들이 손해를 본다면 맹렬한 분노로 변하여 전도자와 교회를 공격하는 것이다. 예를 들면 타 종교인과 불신자들이 있다. 
- 오늘날 세상 사람들은 자신의 신앙(불신 포함), 세계관이 복음과 상반될 때 우리를 공격한다. 그리고 기독교를 편협한 종교 또는 문화를 어지럽히는 종교라고 말한다. 
- 우리는 이런 일에 준비가 되어 있어야 하며, 세상과 타협하지 않고 십자가 복음을 전해야 한다.

10. 영적터치(단어/구절)  
21 내가 거기 갔다가 후에 로마도 보아야 하리라 

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-27', '사도행전', '19장 31절 ~ 41절', '제목 없음', '(사도행전 19장)
30. 바울이 백성 가운데로 들어가고자 하나 제자들이 말리고
31. 또 아시아 관리 중에 바울의 친구된 어떤 이들이 그에게 통지하여 연극장에 들어가지 말라 권하더라
32. 사람들이 외쳐 어떤 이는 이런 말을, 어떤 이는 저런 말을 하니 모인 무리가 분란하여 태반이나 어찌하여 모였는지 알지 못하더라
33. 유대인들이 무리 가운데서 알렉산더를 권하여 앞으로 밀어내니 알렉산더가 손짓하며 백성에게 변명하려 하나
34. 그들은 그가 유대인인 줄 알고 다 한 소리로 외쳐 이르되 크다 에베소 사람의 아데미여 하기를 두 시간이나 하더니
35. 서기장이 무리를 진정시키고 이르되 에베소 사람들아 에베소 시가 큰 아데미와 제우스에게서 내려온 우상의 신전지기가 된 줄을 누가 알지 못하겠느냐
36. 이 일이 그렇지 않다 할 수 없으니 너희가 가만히 있어서 무엇이든지 경솔히 아니하여야 하리라
37. 신전의 물건을 도둑질하지도 아니하였고 우리 여신을 비방하지도 아니한 이 사람들을 너희가 붙잡아 왔으니
38. 만일 데메드리오와 그와 함께 있는 직공들이 누구에게 고발할 것이 있으면 재판 날도 있고 총독들도 있으니 피차 고소할 것이요
39. 만일 그 외에 무엇을 원하면 정식으로 민회에서 결정할지라
40. 오늘 아무 까닭도 없는 이 일에 우리가 소요 사건으로 책망 받을 위험이 있고 우리는 이 불법 집회에 관하여 보고할 자료가 없다 하고
41. 이에 그 모임을 흩어지게 하니라

