2023년 8월14일 사도행전 20장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
하나님: 21, 24, 25, 27, 28
예수: 21, 24
성령: 22, 23, 28
내가: 24, 25, 26, 27, 29
양: 28, 29

4.주제 만들기: 사명에 대한 마음가짐  

5.하나님 찾기 (관찰)
- 예루살렘으로 보내시고, 결박과 환난이 기다린다 말씀하시는 성령 하나님

6.인간 찾기 (관찰)
- 사명을 이루는 일에는 생명조차 귀하게 여기지 않는다고 선포하는 바울
- 제자들에게 다시는 만날 수 없음을 이야기하며 그동안 자신이 하나님의 뜻을 전한 것을 말함
- 감독자를 세우며 자신이 떠난 후에 교회를 잘 다스릴 것을 부탁하는 바울
- 교회에 이리의 공격이 있을 것과 감독자들 중에 분열을 일으킬 자가 있을 것임을 말하는 바울
 
7.하나님 찾기 (해석) 

8.인간(해석): 
- 예수님께서 주신 사명을 마치는 일에는 자신의 생명조차 중요치 않다고 말하는 바울. 보이는 것을 주목하지 않고 보이지 않는 것을 주목했으며, 현재의 고난과 장차 받을 영광은 비교할 수 없음을 알았으며, 잠시 잠깐의 삶과 영원의 삶에 대해 잘 알았으며, 사랑하는 예수님 품에서의 삶은 얼마나 큰 기쁨이 있을지 잘 알았기에 가능한 고백이었을 것이다.
- 다시 돌아올 수 없는 교회를 위해 믿을 만한 사람을 감독자로 세우며 교회를 잘 지킬 것을 당부하는 바울. 교회와 성도들을 얼마나 사랑했는지 알 수 있다.
- 교회를 공격하는 세력이 있을 것임을 말하는 바울. 복음의 전진기지인 교회는 세상에게 분명한 공격 대상이다.

9. 적용(나): 
- 예수님께서 주신 사명은 목숨 바쳐 마쳐야 한다. 사명을 이루는 일에는 고난과 역경이 반드시 있다. 그것을 힘겨워 하거나, 걱정할 것이 아니라 예수님의 영광을 바라보며 맡기신 일을 위해 앞으로 뚜벅뚜벅 걸어가야 한다.
- 교회와 성도를 사랑해야 한다. 사랑하는 마음으로 교회와 성도를 위해 기도하고, 말씀을 바르게, 정직하게 전해야 한다. 성도들이 나를 따르게 하기 위해 어그러진 말을 해서는 안 된다. 말씀은 반드시 바르고 정직하게 선포해야 한다.
- 세상의 공격을 두려워 하지 말고, 그것에 주춤거리지 않고, 그것에 집중하지 않고 의연하게 대하며 복음의 전진기지로서 삶을 살고, 복음을 전파해야 한다.

10. 영적터치(단어/구절)  
24 내가 달려갈 길과 주 예수께 받은 사명 곧 하나님의 은혜의 복음을 증언하는 일을 마치려 함에는 나의 생명조차 조금도 귀한 것으로 여기지 아니하노라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-07-31', '사도행전', '20장 31절 ~ 40절', '여러분', '[행20:31-38]
31 그러므로 여러분이 일깨어 내가 삼 년이나 밤낮 쉬지 않고 눈물로 각 사람을 훈계하던 것을 기억하라
32 지금 내가 여러분을 주와 및 그 은혜의 말씀에 부탁하노니 그 말씀이 여러분을 능히 든든히 세우사 거룩하게 하심을 입은 모든 자 가운데 기업이 있게 하시리라
33 내가 아무의 은이나 금이나 의복을 탐하지 아니하였고
34 여러분이 아는 바와 같이 이 손으로 나와 내 동행들이 쓰는 것을 충당하여
35 범사에 여러분에게 모본을 보여준 바와 같이 수고하여 약한 사람들을 돕고 또 주 예수께서 친히 말씀하신 바 주는 것이 받는 것보다 복이 있다 하심을 기억하여야 할지니라
36 이 말을 한 후 무릎을 꿇고 그 모든 사람들과 함께 기도하니
37 다 크게 울며 바울의 목을 안고 입을 맞추고
38 다시 그 얼굴을 보지 못하리라 한 말로 말미암아 더욱 근심하고 배에까지 그를 전송하니라

