4.주제만들기 : 여러분
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 3년간 쉬지 않고 눈물로 훈계하던 것을 기억하라고 말한다.
- 말씀이 능히 든든하게 세우고 거룩함을 입은 모든 사람 가운데 기업을 받게 할 것이라 말함.
- 바울은 은이나 금을 탐한 적이 없고 자신과 동행자의 필요를 손수 벌어서 사용했으며 약한 사람을 돕고 받는 것보다 주는 것이 복이 있다는 주의 말씀을 기억해야 한다고 말함
- 무릎을 꿇고 함께 기도함
- 바울을 위해 울며 입을 맞추며 바울을 배웅함.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울이 동역자들에게 마지막으로 한 말은 말씀을 기억하고 붙잡으라는 것이었다. 말씀이 중심이 되어야 닥쳐올 많은 고초를 이겨낼 수 있다는 것을 강조하였다. 그리고 자신이 본을 보인 이유도 자신의 의로움을 나타내려는 것이 아니라 하나님의 말씀을 쫓아 행동했다는 것을 강조한다. 바울 자신이 우상이 되지 않도록 순종의 자세를 보여준다. 마치 예수님께서 하나님의 말씀을 순종하신 것처럼 바울도 예수님의 말씀에 순종했다.  
9. 적용(나): 
- 바울과 같은 영적 지도자가 한 순간 사라진다면 공동체는 어떻게 될까? 리더의 자리가 크기 때문에 성도들은 많은 어려움을 겪을 수 있다. 그러나 말씀을 의지하면 리더의 빈자리를 지혜롭게 채워나갈 수 있다. 
- 바울은 자신의 업적을 드러내지 않으려 끝까지 낮은 자세를 취한다. NKFC의 사역도 마찬가지이다. 우리의 사역은 하나님이 이끄시는 사역이다. 우리의 업적이 아니라 하나님께서 이끄심을 감사하며 겸손함으로 나아가야한다. 그리고 리더십 중 누구라도 리더의 자리에서 목사님의 빈자리를 채울 수 있는 영적 리더십도 채워가야 한다. 
10. 영적터치(단어/구절) 모본을 보여준 바와 같이
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-01', '사도행전', '21장 1절 ~ 10절', '성령의 감동', '[행21:1-10]
1.우리가 저희를 작별하고 행선하여 바로 고스로 가서 이튿날 로도에 이르러 거기서부터 바다라로 가서
2.베니게로 건너가는 배를 만나서 타고 가다가
3.구브로를 바라보고 이를 왼편에 두고 수리아로 행선하여 두로에서 상륙하니 거기서 배가 짐을 풀려 함이러라
4.제자들을 찾아 거기서 이레를 머물더니 그 제자들이 성령의 감동으로 바울더러 예루살렘에 들어가지 말라 하더라
5.이 여러 날을 지난 후 우리가 떠나갈쌔 저희가 다 그 처자와 함께 성문 밖까지 전송하거늘 우리가 바닷가에서 무릎을 끓어 기도하고 
6.서로 작별한 후 우리는 배에 오르고 저희는 집으로 돌아가니라
7.두로로부터 수로를 다 행하여 돌레마이에 이르러 형제들에게 안부를 묻고 그들과 함께 하루를 있다가 
8.이튿날 떠나 가이사랴에 이르러 일곱 집사 중 하나인 전도자 빌립의 집에 들어가서 유하니라
9.그에게 딸 넷이 있으니 처녀로 예언하는 자라
10.여러 날 있더니 한 선지자가 아가보라 하는 이가 유대로부터 내려와

