2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)

4.주제만들기 : 성령의 감동
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
제자들, 전도자, 선지자 아가보
7.하나님 찾기 (해석) 
8.인간(해석):
-제자들이 성령의 감동으로 바울에게 예루살렘으로 들어가지 말 것을 부탁한다. 그럼에도 불구하고 바울은 예루살렘에서 핍박을 당할 것을 알고도 복음을 전하기 위해 예루살렘으로 향한다. 

9. 적용
-나는 복음을 전하다 핍박을 당해 본적이 있는가? 바울처럼 목숨 걸고 복음을 전해 봤는가? 목숨 걸고 복음을 전할 의향은 있는가? 조금만 어려움이 닥쳐와도 무너지는 나를 보면서 바울이 얼마나 영적으로 멋있는 사람인지 다시 한 번 돌아보게 된다. 물론 이런 바울도 바로 복음을 진짜로 깨달았기에 가능했다고 볼 수 있다. 마귀는 우리에게 이렇게 속삭인다. 그런 모습으로 어떻게 하나님을 믿을 수 있겠어. 니 꼴을 좀봐. 하지만 하나님은 괜찮아. 그런 모습마저도 내가 사랑한단다. 라고 격려하시고 위로하신다. 그리고 우리를 사랑하셨기에 십자가에 달리기까지 우리를 사랑하셨고 죄에서 끊으셨고 사망 권세를 이겼다. 이게 복음이다. 오늘도 다시 한번 부족하고 연약하고 넘어지는 내 모습에 실망하다가도 십자가를 바라보며 다시 일어선다. 우리 믿음의 선배들이 꿋꿋이 걸어간 그 좁은 길을 향해 나도 갈 수 있기를 소망한다. 

10. 영적터치(단어/구절) 
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-02', '사도행전', '21장 11절 ~ 20절', '주의 뜻대로 이루어지이다&nbsp;', '(사도행전 21장)
11 우리에게 와서 바울의 띠를 가져다가 자기 수족을 잡아매고 말하기를 성령이 말씀하시되 예루살렘에서 유대인들이 이같이 이 띠 임자를 결박하여 이방인의 손에 넘겨 주리라 하거늘
12 우리가 그 말을 듣고 그 곳 사람들과 더불어 바울에게 예루살렘으로 올라가지 말라 권하니
13 바울이 대답하되 여러분이 어찌하여 울어 내 마음을 상하게 하느냐 나는 주 예수의 이름을 위하여 결박 당할 뿐 아니라 예루살렘에서 죽을 것도 각오하였노라 하니
14 그가 권함을 받지 아니하므로 우리가 주의 뜻대로 이루어지이다 하고 그쳤노라
15 이 여러 날 후에 여장을 꾸려 예루살렘으로 올라갈새
16 가이사랴의 몇 제자가 함께 가며 한 오랜 제자 구브로 사람 나손을 데리고 가니 이는 우리가 그의 집에 머물려 함이라
17 예루살렘에 이르니 형제들이 우리를 기꺼이 영접하거늘
18 그 이튿날 바울이 우리와 함께 야고보에게로 들어가니 장로들도 다 있더라
19 바울이 문안하고 하나님이 자기의 사역으로 말미암아 이방 가운데서 하신 일을 낱낱이 말하니
20 그들이 듣고 하나님께 영광을 돌리고 바울더러 이르되 형제여 그대도 보는 바에 유대인 중에 믿는 자 수만 명이 있으니 다 율법에 열성을 가진 자라

