2023년 8월17일 사도행전 21장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
우리: 11, 12 16, 17, 18
바울: 11, 12, 18, 19, 20
예루살렘: 11, 12, 13, 15, 17
주: 13, 14
하나님 19, 20

4.주제 만들기: 주의 뜻대로 이루어지이다 

5.하나님 찾기 (관찰)
- 바울에게 일어날 일을 여러 사람에게 보이신 성령 하나님

6.인간 찾기 (관찰)
- 바울이 예루살렘에서 결박당하여 이방인에게 넘겨질 것을 말하는 선지자
- 이 말을 듣고 예루살렘으로 가지 말 것을 울며 권하는 제자들
- 결박뿐만 아니라 죽음도 각오했음을 말하는 바울
- 주의 뜻대로 이루이지이다 하며 자신의 주장을 굽힌 제자들
- 예루살렘으로 올라가는 바울과 몇몇 제자들
- 야고보를 만나 하나님의 역사하심을 말하는 바울

7.하나님 찾기 (해석) 

8.인간(해석): 
- 바울을 사랑하는 마음으로 결박당한 것을 말한 선지자와 그 말을 듣고 예루살렘으로 가지 말라고 권한 제자들. 이들은 사명에 대한 바울의 의지가 얼마나 강한지 알고 있었기에 울면서 권하였다. 가면 죽는다 그러니 가지 말아달라.
- 권함을 받은 바울은 사랑하는 동역자들의 눈물의 만류에 가슴이 찢어졌지만, 주님이 주신 사명을 이루는 일이기에 죽음을 각오하였노라 말함.
- 주의 뜻대로 이루어지이다 하며 자신들의 주장을 내려놓은 제자들. 이들은 자신들의 뜻을 내려놓고 주님의 뜻을 바랄 줄 아는 겸손한 자들이다. 교회에서 사역할 때 본받아야 할 부분이다. 하나님의 일을 할 때에는 동역자가 서로를 존중하고 주님의 뜻이 이루어지길 바랄 줄 알아야 한다. 자기 생각과 주장이 옳다고 끝까지 주장해서는 안 된다. 우리는 부분적으로 알고 부분적으로 깨달을 뿐이다. 
- 바울이 결박당할 것을 알고도 함께한 몇몇 제자들. 이들은 바울 못지않은 믿음의 사람들이다.

9. 적용(나): 
- 바울의 비전에 대한 열정과 의지. 그 태도를 본받아야 한다.
- 주님의 뜻이 이루어지길 바라며 자신들의 주장을 내려놓은 제자들의 겸손함을 본받아야 한다. “가면 결박당한다니까 가긴 왜가?” 이게 아니라 “주님의 뜻이 이루어지길 원한다.” 가 되어야 한다.
- 바울이 결박당할 것을 알고도 함께 한 제자들이 있다. 이런 믿음의 동역자가 되어야 한다.
믿음의 사람들은 두려움보다 사랑의 힘이 강하다.

10. 영적터치(단어/구절)  
14 그가 권함을 받지 아니하므로 우리가 주의 뜻대로 이루어지이다 하고 그쳤노라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-03', '사도행전', '21장 21절 ~ 30절', '복음이 전파될수록 커지는 방해', '[행21:21-30]
21 네가 이방에 있는 모든 유대인을 가르치되 모세를 배반하고 아들들에게 할례를 행하지 말고 또 관습을 지키지 말라 한다 함을 그들이 들었도다
22 그러면 어찌할꼬 그들이 필연 그대가 온 것을 들으리니
23 우리가 말하는 이대로 하라 서원한 네 사람이 우리에게 있으니
24 그들을 데리고 함께 결례를 행하고 그들을 위하여 비용을 내어 머리를 깎게 하라 그러면 모든 사람이 그대에 대하여 들은 것이 사실이 아니고 그대도 율법을 지켜 행하는 줄로 알 것이라
25 주를 믿는 이방인에게는 우리가 우상의 제물과 피와 목매어 죽인 것과 음행을 피할 것을 결의하고 편지하였느니라 하니
26 바울이 이 사람들을 데리고 이튿날 그들과 함께 결례를 행하고 성전에 들어가서 각 사람을 위하여 제사 드릴 때까지의 결례 기간이 만기된 것을 신고하니라
27 그 이레가 거의 차매 아시아로부터 온 유대인들이 성전에서 바울을 보고 모든 무리를 충동하여 그를 붙들고
28 외치되 이스라엘 사람들아 도우라 이 사람은 각처에서 우리 백성과 율법과 이 곳을 비방하여 모든 사람을 가르치는 그 자인데 또 헬라인을 데리고 성전에 들어가서 이 거룩한 곳을 더럽혔다 하니
29 이는 그들이 전에 에베소 사람 드로비모가 바울과 함께 시내에 있음을 보고 바울이 그를 성전에 데리고 들어간 줄로 생각함이러라
30 온 성이 소동하여 백성이 달려와 모여 바울을 잡아 성전 밖으로 끌고 나가니 문들이 곧 닫히더라

