4.주제만들기 : 복음이 전파될수록 커지는 방해
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 예루살렘에 도착한 바울은 형제들이 바울이 왔다는 소문을 듣고 바울을 헤할 것을 알고 정결의식에 참여할 것을 말함.
- 바울이 정결의식에 참여하고 7일 동안 정결기간이 끝나갈 무렵 유대 사람들이 성전에서 바울을 보고 사람들을 선동해 바울을 붙잡게 함
7.하나님 찾기 (해석) 
8.인간(해석):
- 유대 사람들은 바울이 드로비모와 예루살렘에 있던 것을 보고 바울에 대한 분노와 바울을 잡을 기회를 엿보고 있었던 것으로 보인다. 대중을 선동할 기회를 엿보고 있던 유대 사람들은 정결 기간을 틈타 바울을 붙잡고자 대중들을 선동한다.
9. 적용(나): 
- 선교지에서 예수님을 전하는 선교사님들의 모습이 이러할까라는 생각이 들었다. 선교지에 복음이 들어갈 때, 복음이 온전히 뿌리를 내리기도 하지만 복음을 거부하는 사람들도 많다. 그럴 때 복음을 통해 변화되는 사람과 지역을 보며 시기질투를 하다 사역의 방해요소를 만들 수 있는 때를 기다릴 것이다. 그리고 갖은 이유로 사역을 방해하거나 위협하거나 실제 행동으로 옮기기도 한다. 선교사님들을 위해 기도해야겠다. 
- 나는 과연 대중의 시선을 이겨내며 복음을 전하고 중심을 잡을 수 있을까? 내 힘으로 불가능한 영역이기에 하나님께 용기와 인내와 사랑을 기도한다. 
10. 영적터치(단어/구절) : 충동하여 붙잡고
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-04', '사도행전', '21장 31절 ~ 40절', '제목 없음', '(사도행전 21장)
31. 그들이 그를 죽이려 할 때에 온 예루살렘이 요란하다는 소문이 군대의 천부장에게 들리매
32. 그가 급히 군인들과 백부장들을 거느리고 달려 내려가니 그들이 천부장과 군인들을 보고 바울 치기를 그치는지라
33. 이에 천부장이 가까이 가서 바울을 잡아 두 쇠사슬로 결박하라 명하고 그가 누구이며 그가 무슨 일을 하였느냐 물으니
34. 무리 가운데서 어떤 이는 이런 말로, 어떤 이는 저런 말로 소리 치거늘 천부장이 소동으로 말미암아 진상을 알 수 없어 그를 영내로 데려가라 명하니라
35. 바울이 층대에 이를 때에 무리의 폭행으로 말미암아 군사들에게 들려가니
36. 이는 백성의 무리가 그를 없이하자고 외치며 따라 감이러라
37.  바울을 데리고 영내로 들어가려 할 그 때에 바울이 천부장에게 이르되 내가 당신에게 말할 수 있느냐 이르되 네가 헬라 말을 아느냐
38. 그러면 네가 이전에 소요를 일으켜 자객 사천 명을 거느리고 광야로 가던 애굽인이 아니냐
39. 바울이 이르되 나는 유대인이라 소읍이 아닌 길리기아 다소 시의 시민이니 청컨대 백성에게 말하기를 허락하라 하니
40. 천부장이 허락하거늘 바울이 층대 위에 서서 백성에게 손짓하여 매우 조용히 한 후에 히브리 말로 말하니라

