바울: 3절 4절 7절 8절 10절

4. 주제 만들기
대중들에게 변명하는 바울

5.하나님 찾기(관찰)
바울을 부르시는 예수

6.인간 찾기(관찰)
유대인들 앞에서 예수님을 어떻게 만났는지 변명하는 바울

7.하나님 찾기(해석)

8. 인간 찾기 (해석)
유대인들 앞에서 자신의 신앙고백을 하고 있는 바울.
바울 자신을 옥죄는 유대인들 앞에서 그들에게 단순한 목숨을 구걸하기위한 변명이 아닌 핍박자였던 자신에게 찾아오신 예수, 스스로가 믿게된 경위를 알리고 있다.
위기를 복음전파의 기회를 삼는 지혜를 볼수있다.

9. 적용(나)
사도바울 처럼 항상 복음을 전파할준비와 목숨도 아끼지 않는 헌신적자세를 갖는 종이 되야겠다.
10. 영적터치(단어/구절)
 10절: 일어나 다메섹으로 들어가라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-06', '사도행전', '22장 11절 ~ 20절', '제목 없음', '(사도행전 22장)
11 나는 그 빛의 광채로 말미암아 볼 수 없게 되었으므로 나와 함께 있는 사람들의 손에 끌려 다메섹에 들어갔노라
12 율법에 따라 경건한 사람으로 거기 사는 모든 유대인들에게 칭찬을 듣는 아나니아라 하는 이가
13 내게 와 곁에 서서 말하되 형제 사울아 다시 보라 하거늘 즉시 그를 쳐다보았노라
14 그가 또 이르되 우리 조상들의 하나님이 너를 택하여 너로 하여금 자기 뜻을 알게 하시며 그 의인을 보게 하시고 그 입에서 나오는 음성을 듣게 하셨으니
15 네가 그를 위하여 모든 사람 앞에서 네가 보고 들은 것에 증인이 되리라
16 이제는 왜 주저하느냐 일어나 주의 이름을 불러 세례를 받고 너의 죄를 씻으라 하더라
17 후에 내가 예루살렘으로 돌아와서 성전에서 기도할 때에 황홀한 중에
18 보매 주께서 내게 말씀하시되 속히 예루살렘에서 나가라 그들은 네가 내게 대하여 증언하는 말을 듣지 아니하리라 하시거늘
19 내가 말하기를 주님 내가 주를 믿는 사람들을 가두고 또 각 회당에서 때리고
20 또 주의 증인 스데반이 피를 흘릴 때에 내가 곁에 서서 찬성하고 그 죽이는 사람들의 옷을 지킨 줄 그들도 아나이다

