2023년 7월 27일 사도행전 15장 21~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)


4. 주제 만들기
주제: 복음의 불순물을 제거하는 제자들 

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 다메섹에서 예수님을 만난 것을 무리들에게 말함. 
- 아나니아를 통해 눈을 뜨게 되었으며, 하나님의 택하심으로 바울이 모든 사람 앞에서 예수님의 증인이 될 것을 아나니아에게 들었음을 이야기 함.
- 예루살렘에서 기도하는 중에 예루살렘에서 속히 나가라는 예수님의 음성을 들음
- 예수님께 내가 예수님 믿는 자들을 핍박하던 것을 그들도 알고 있다고 말하는 바울

7.하나님 찾기(해석)
- 바울에게 속히 예루살렘에서 나가라고 말씀하시는 예수님 

8. 인간(해석)
- 예언대로 예루살렘에서 유대인에게 결박되어 로마 군인에게 넘겨진 바울은 자신을 결박하고 죽이려고 때리던 유대인들에게 예수님의 역사하심에 대해 이야기 함.
- 이때 정확한 지명과 인물을 이야기하면서 자신이 하는 이야기가 사실임을 나타내고자 함.
- 예루살렘에서 기도 중에 예수님께서 그들은 너의 말을 듣지 않을 것이니 속히 예루살렘에서 나가라고 하실 때 내가 주를 믿는 사람들을 핍박하던 사람인 줄 그들도 아나이다라고 말한 것을 이야기함. 이 말은 첫째 예수님께는 “이들이 갑자기 변한 나를 알기에 핍박하던 자가 오히려 예수님을 전하는 것을 보면 뭔가 있을 것이다 생각할 것입니다. 이들도 믿을 수 있습니다.” 라는 말이고.
  둘째, 유대인들에게는 “너희가 나를 결박하고 죽이고자 했으나 나 또한 믿는 사람들을 가두고 때리고 죽였던 사람이다. 그런 내가 예수님을 믿는 것에는 확실한 이유가 있다.” 라는 의미일 것이다.
- 바울이 자신을 핍박하는 자들에게 끝까지 복음을 전하는 것은 유대인들도 자신처럼 깨닫고 돌아오기를 간절히 바라는 것이다.

9. 적용(나)
- 복음 때문에 나를 공격하고 험담하는 사람들은 내가 미워할 대상이 아니라 내가 믿는 예수님에 대해 말해야 하는 대상이다.
- 현재 복음 때문에 나를 핍박하는 사람은 없다. 그저 가까이하지 않을 뿐이다. 어려워하거나 불편해할 뿐이다. 나는 묵묵히 이들에게 내가 경험한 예수님을 이야기해야 한다. 나도 쾌락을 추구하는 사람이었음을, 교회에 다니지만 믿음이 없었음을, 그러나 예수님의 능력으로 변화되었음을 이야기해야 한다. 그리고 나아가 지금도 죄를 짓고 있으며 다만, 과거와 다르게 지금은 죄와 싸우고 있음을 이야기해야 한다. 예수님의 능력으로 변화되었음을 오직 은혜임을 말해야 한다.
- 지금은 내가 말해도 듣지 않는 사람들이 있다. 그러나 다시 말해야 하는 때가 있다. 때는 주님만 아신다. 기도에 힘쓰며 성령님의 음성에 귀 기울여야 한다. 그리고 다시 말해야 한다.
 
10. 영적터치(단어/구절)
18 그들은 네가 내게 대하여 증언하는 말을 듣지 아니하리라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-07', '사도행전', '22장 21절 ~ 30절', '주님을 위해 사용하는 권리', '[행22:21-30]
21 나더러 또 이르시되 떠나가라 내가 너를 멀리 이방인에게로 보내리라 하셨느니라
22 이 말하는 것까지 그들이 듣다가 소리 질러 이르되 이러한 자는 세상에서 없애 버리자 살려 둘 자가 아니라 하여
23 떠들며 옷을 벗어 던지고 티끌을 공중에 날리니
24 천부장이 바울을 영내로 데려가라 명하고 그들이 무슨 일로 그에 대하여 떠드는지 알고자 하여 채찍질하며 심문하라 한대
25 가죽 줄로 바울을 매니 바울이 곁에 서 있는 백부장더러 이르되 너희가 로마 시민 된 자를 죄도 정하지 아니하고 채찍질할 수 있느냐 하니
26 백부장이 듣고 가서 천부장에게 전하여 이르되 어찌하려 하느냐 이는 로마 시민이라 하니
27 천부장이 와서 바울에게 말하되 네가 로마 시민이냐 내게 말하라 이르되 그러하다
28 천부장이 대답하되 나는 돈을 많이 들여 이 시민권을 얻었노라 바울이 이르되 나는 나면서부터라 하니
29 심문하려던 사람들이 곧 그에게서 물러가고 천부장도 그가 로마 시민인 줄 알고 또 그 결박한 것 때문에 두려워하니라
30 이튿날 천부장은 유대인들이 무슨 일로 그를 고발하는지 진상을 알고자 하여 그 결박을 풀고 명하여 제사장들과 온 공회를 모으고 바울을 데리고 내려가서 그들 앞에 세우니라

