2023년 8월22일 사도행전 22장 21절~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-천부장(24,28,29,30절), 로마시민(25,26,27,29절), 채찍질(24,25절),
4.주제만들기 : 주님을 위해 사용하는 권리
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 천부장이 바울을 영내로 데려가라 명하고 채찍질로 심문하라 지시함
- 바울은 백부장에게 로마 시민이라 말하며 죄도 정하지 않고 채찍질할 수 있냐고 말함
- 백부장은 천부장에게 이 사실을 전달하고 천부장은 바울에게 사실 확인을 하는데 자신은 로마 시민권을 돈주고 샀다함. 바울은 나면서부터 시민권자라하니 두려워함
- 이튿날 천부장은 유대인들에게 왜 고발했는지 알고자 제사장들과 공회를 모아 바울을 그들 앞에 세움 
7.하나님 찾기 (해석) 
8.인간(해석):
- 백부장과 천부장은 바울의 죄목이 중요한게 아니라 유대인과 제사장들 공회 사람들이 분노하는 것에 집중해있다. 로마 시민권은 당시 다양한 권리와 혜택을 받을 수 있다고 하는데 바울은 태어나면서부터 로마 시민권을 받았기 때문에 귀족 출신이라는 것을 알고 혹시 잘못될지 두려워한다. 
- 바울에겐 로마 시민권이 중요하지 않다. 바울에게 있어 로마 시민권은 로마에서 전달해야 할 복음, 즉 사명을 위해 쓰이는 도구에 불가하지 않다. 자신의 이득을 위해 사용하는 것이 아닌 예수님을 전하기 위한 도구로만 사용했다.
9. 적용(나): 
- 권력과 힘이 내게 있다면 나는 어떻게 사용했을까? 나의 지위를 나의 능력과 나의 노력의 대가라 생각하고 권위있고 교만한 모습으로 살지 않았을까? 아무 힘이 없는 교사로 지내는 삶이 오히려 하나님께서 주신 축복이 아닌가 생각한다.
- 그럼에도 감사가 나와야 하는데 교사라는 직업에 대해 고민을 많이 하게 된다. 하나님께서 주신 직업과 직장에서 최선을 다해야하는데 그러지 못한다. 마음을 다 잡고 하나님의 음성을 쫓아 성실히 나의 역할을 다해야겠다. 
- 사역함에 있어 내가 예수님을 더 안다라는 착각에 권위있는 행동과 교만한 행동이 나오지 않도록 오직 성령님만 바라고 겸손함을 달라고 기도해야겠다. 우리의 사역이 힘있는 사람들보다는 도움이 필요한 곳으로 향하기 때문에 교만하지 않도록 예수님만 바라보아야겠다. 
10. 영적터치(단어/구절) 나는 나면서부터라 하니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-08', '사도행전', '23장 1절 ~ 10절', '제목 없음', '(사도행전 23장)
1. 바울이 공회를 주목하여 이르되 여러분 형제들아 오늘까지 나는 범사에 양심을 따라 하나님을 섬겼노라 하거늘
2. 대제사장 아나니아가 바울 곁에 서 있는 사람들에게 그 입을 치라 명하니
3. 바울이 이르되 회칠한 담이여 하나님이 너를 치시리로다 네가 나를 율법대로 심판한다고 앉아서 율법을 어기고 나를 치라 하느냐 하니
4. 곁에 선 사람들이 말하되 하나님의 대제사장을 네가 욕하느냐
5. 바울이 이르되 형제들아 나는 그가 대제사장인 줄 알지 못하였노라 기록하였으되 너의 백성의 관리를 비방하지 말라 하였느니라 하더라
6. 바울이 그 중 일부는 사두개인이요 다른 일부는 바리새인인 줄 알고 공회에서 외쳐 이르되 여러분 형제들아 나는 바리새인이요 또 바리새인의 아들이라 죽은 자의 소망 곧 부활로 말미암아 내가 심문을 받노라
7. 그 말을 한즉 바리새인과 사두개인 사이에 다툼이 생겨 무리가 나누어지니
8. 이는 사두개인은 부활도 없고 천사도 없고 영도 없다 하고 바리새인은 다 있다 함이라
9. 크게 떠들새 바리새인 편에서 몇 서기관이 일어나 다투어 이르되 우리가 이 사람을 보니 악한 것이 없도다 혹 영이나 혹 천사가 그에게 말하였으면 어찌 하겠느냐 하여
10. 큰 분쟁이 생기니 천부장은 바울이 그들에게 찢겨질까 하여 군인을 명하여 내려가 무리 가운데서 빼앗아 가지고 영내로 들어가라 하니라

