공회 앞에서 증언하는 바울

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
바울의 입을 치라 명령하는 대제사장 아나니아
이에 맞서는 바울
바울의 증언으로 바리새인과 사두개인의 다툼
부활과 천사 그리고 영도 부정하는  사두개인

7.하나님 찾기(해석)

8. 인간 찾기 (해석)
공회 앞에서 자신을 위협하는 대제사장 아나니아 에게 당당하게 말로 대항하는 사도바울.
자신을 핍박하려 연합하는 종교집단들에게 지혜롭게 대처하는 바울의 태도를 볼수있다. 바울은 천사와 부활을 믿는 바리새인들과 그것을  인정하지 않는  사두개인들의 틈을 벌려 위기를 모면한다. 
바울은 꼭 필요할때 자신의 신분을 적당하게 사옹한다. 자신을 돋보일일수 있는 로마 시민권이나 바리새인 출신등을 과시용으로 사옹하지않고 꼭 필요할때만 사용하는 바울의 겸손함을 볼수있다.

9. 적용(나)
늘 겸손하며 당당하고 지혜롭게 사는 종이 되야겠다.
