2023년 8월 24일 사도행전 23장 11~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
바울: 11, 12, 14, 15, 16(2), 17, 18
유대인: 12, 20
천부장: 15, 17, 18, 19

4. 주제 만들기
주제: 로마에 가서 복음을 전하라

5.하나님 찾기 (관찰)
- 바울에게 로마에서도 복음을 전하라고 말씀하시는 하나님
 
6.인간 찾기 (관찰)
- 유대인 사십여 명이 바울이 죽이기 전에는 식음을 전폐하기로 결정함.
- 바울을 죽임 음모를 꾸밈
- 바울의 생질이 유대인들의 음모를 듣고 바울에게 알림
- 바울이 생질이 이 음모가 있음을 천부장에게 알림

7.하나님 찾기(해석)
- 너희 이스라엘 백성들이 미워하는 로마에도 내가 사랑하는 자녀들이 많으니 가서 전하라

8. 인간(해석)
- 이스라엘을 지배하던 로마에 복음을 전하라는 하나님의 명령이 인간의 마음에는 괴로울 수 있는 일인데도 불구하고 바울은 그저 순종한다. 성령님을 깊이 체험한 사람들은 그 마음가짐이 다르다.
- 유대인 사십여 명이 식음을 전폐하고 바울을 죽이겠다고 맹세한 것은 첫째, 기필코 죽이겠다는 것이고 둘째, 빠른 시일 내에 죽이겠다는 것이다.
- 자신들을 비난하는 것도 공격하는 것도 아닌데 이 유대인들은 바울을 죽도록 증오한 것이다.
- 그러나 바울은 이들을 누구보다 잘 이해하고 긍휼함을 느꼈을 것이다. 사십여명의 유대인들처럼 제자들을 박해하던 시절이 있었기 때문이다.
- 예수님을 만나면 한 인간의 세계관이 변한다. 이것은 자연법칙을 거스르는 기적만큼 대단한 일이다. 

9. 적용(나)
- 나에게 로마인 같은 존재가 있는가? 없다. 없어서 다행이다. 
- 내 생각, 내 판단으로 전도 대상자를 생각하는 것이 아니라, 하나님께서 전하라 하시면 순종하고 전해야 한다.
- 자신의 가치관과 세계관을 변호하기 위해서 열심으로 나를 험담하는 사람들이 있을 수 있다. 그들을 긍휼히 여겨야 한다. 그들을 긍휼히 여기며 겸손하게 대해야 한다.
- 나를 변화시킨 놀라우신 하나님이 나를 험담하고 공격하는 사람들도 변화시킬 것을 기대하며 기도해야 한다. 그리고 그 공격에 흔들리는 것이 아니라 담대해야 한다. 그저 의연하게 대처하고 내게 주어진 길을 묵묵히 걸어가야 한다.
 
10. 영적터치(단어/구절)
- 11절 담대하라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-10', '사도행전', '23장 21절 ~ 30절', '사명을 위해 인간의 탐욕을 사용하시는 하나님', '[행23:21-30]
21 당신은 그들의 청함을 따르지 마옵소서 그들 중에서 바울을 죽이기 전에는 먹지도 않고 마시지도 않기로 맹세한 자 사십여 명이 그를 죽이려고 숨어서 지금 다 준비하고 당신의 허락만 기다리나이다 하니
22 이에 천부장이 청년을 보내며 경계하되 이 일을 내게 알렸다고 아무에게도 이르지 말라 하고
23 백부장 둘을 불러 이르되 밤 제 삼 시에 가이사랴까지 갈 보병 이백 명과 기병 칠십 명과 창병 이백 명을 준비하라 하고
24 또 바울을 태워 총독 벨릭스에게로 무사히 보내기 위하여 짐승을 준비하라 명하며
25 또 이 아래와 같이 편지하니 일렀으되
26 글라우디오 루시아는 총독 벨릭스 각하께 문안하나이다
27 이 사람이 유대인들에게 잡혀 죽게 된 것을 내가 로마 사람인 줄 들어 알고 군대를 거느리고 가서 구원하여다가
28 유대인들이 무슨 일로 그를 고발하는지 알고자 하여 그들의 공회로 데리고 내려갔더니
29 고발하는 것이 그들의 율법 문제에 관한 것뿐이요 한 가지도 죽이거나 결박할 사유가 없음을 발견하였나이다
30 그러나 이 사람을 해하려는 간계가 있다고 누가 내게 알려 주기로 곧 당신께로 보내며 또 고발하는 사람들도 당신 앞에서 그에 대하여 말하라 하였나이다 하였더라

