4.주제만들기 : 사명을 위해 인간의 탐욕을 사용하시는 하나님
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울을 죽이려하는 유대인의 계획을 청년이 알고 천부장에게 말함
- 천부장은 보병 이백명과 기병 칠십명, 창병 이백명을 준비시켜 벨릭스에게 바울을 보내려함
- 벨릭스에게 편지를 보내 유대인들이 고발했고 죽이거나 결박할 사유가 없지만 유대인들의 율범과 관련된 일로 유대인들이 바울을 죽이려하고 유대인들도 벨릭스에게 가 바울에 대해 말하길 희망한다고 편지함
7.하나님 찾기 (해석) 
8.인간(해석):
천부장은 바울이 로마 시민임을 알고 머리가 복잡해졌을 것이다. 그러나 자신이 피를 묻히지 않고 바울의 일을 해결할 방법이 생겼다. 바울도 원하고 유대인들도 원하니 벨릭스에게 보내어 일을 처리하면 된다. 천부장은 바울이 헤를 당할까봐 두려운 마음에 자신들의 부하를 시켜 바울을 보호한다. 때로는 인간의 탐욕이 하나님의 일에 도구로 사용되기도 함을 느낀다. 
- 바울은 로마까지 갈 때에 죄인으로서 괴롭게 가지 않고 보호를 받으며 갈 수 있게 되었다.
9. 적용(나):
- 인간의 탐욕은 참으로 무섭다. 그러나 하나님은 사명을 위해 인간의 탐욕까지 사용하신다. 바울의 심정은 어땠을까. 바울은 천부장 옆에서 천부장의 선택을 보았을 것이다. 아마 속으로 하나님께 감사하다고 기도했을까?
- 나라면 바울의 상황에서 어떤 생각을 했을까? 하나님의 뜻과 계획보다 나의 생각이 먼저 앞서서 판단했을 것이다. 나의 잘못된 습관이 그렇다. 먼저 하나님의 뜻을 생각하고 판단하지 말아야 하는데 행동이 앞설 때가 많다.
- 하나님은 완벽하신 분이시기에 하나님의 섭리를 깨달으며 즐기는 삶을 살아가고 싶다. 그리고 아직은 바울과 같이 살아갈 용기가 없다. 이 고비를 뛰어 넘는 날이 오길 소망한다.
10. 영적터치(단어/구절) : 벨릭스에게로 무사히 보내기 위해
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

