총독 벨릭스 에게 연합하여 바울을 고발하는 종교지도자들
총독은 바울에게 변명할 기회를 준다.

7.하나님 찾기(해석)

8. 인간 찾기 (해석)
로마식민지 하에  있었던 유대인 들은 종교지도자인 대제사장 아나나등이 로마총독 벨릭스 에게 바울을 고발한다. 고발하는 내용을 보면 수위가 높다. 바울에 대하여 자세히 살펴보지 않으며 참 진리를 전하는 바울을 향하여 "전염병"이라는 인간적 모독 발언을 서슴치않고 한다. 또한 침략국인 로마에 대하여서는 아첨을 아끼지 않는 모습을 본다. 자신들의 기득권 을 위해서는 그들은 어떠한 것보다도 자신들의 이익이 앞서 영적 눈이 가려져있는것을 알수있다.

9. 적용(나)
사도바울 같은 순수하며 오직 주님나라의 유익을 구하는 종이 되고싶다. 내마음속에 혹시 욕심을 내려놓지 못하는 부분이 있는지 더욱 성찰해야겠다.
