2023년 8월 28일 사도행전 24장 11~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
당신: 11, 13, 14, 19
내가: 11, 12, 17, 18, 20
그들: 12, 13, 14, 18, 19
성전: 12, 18
고발: 13, 19
하나님: 14, 16

4. 주제 만들기
주제: 논리적으로 변론하는 바울

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 변호사 더둘로의 고발에 대해 총독 벨릭스에게 사실과 다르다고 논리적으로 변론하는 바울
- 그들이 이단이라 말하는 것은 하나님을 섬기는 것과 성경과 부활을 믿는 것이며, 이 부활을 위해 양심에 거리낌이 없기를 힘쓰고 있음을 말함.
- 여러 해 만에 제사를 드리며 결례를 행하고 다른 문제 행동은 없었음을 말하는 바울.

7.하나님 찾기(해석)

8. 인간(해석)
- 변호사 더둘로가 거짓으로 죄를 씌우려고 하나, 이에 논리적으로 대응하며 그 말은 사실과 다름을 시간의 흐름에 따라 하나하나 변론하는 바울. 
- 총독 벨릭스에게 그들이 말하는 이단이 하나님과 성경 부활에 대한 것임을 말하며 나는 이 도를 위해 양심에 거리낌이 없기를 힘쓴다고 말함. 사람 앞에서 떳떳할 뿐 아니라 하나님 앞에서 정결하기 위해 양심에 비추어 마음을 정결하게 하기 위해 노력하고 있음을 말함. 
  예수님을 믿는 자들은 마음의 정결을 위해 노력해야 함.
- 예루살렘에서 제사드리고 결례를 행했을 뿐, 죄 지은 것은 없음을 변론하며 아시아에서든 예루살렘에서는 유대인들이 고발할 것이 있으면 고발하게 하라고 총독 벨릭스에게 담대하게 말하는 바울.
- 예루살렘에서 제사드리고 결례를 행했을 뿐이라는 것은 유대인들이 중요시하는 율법을 다 지켰음을 의미함.

9. 적용(나)
- 바울처럼 사실에 입각하여 논리적으로 말하는 사람이 되어야 한다.
- 기독교에 의문을 품고 공격하되 논리로 공격하는 사람들에게 역사적 사실을 이야기 하며 논리적으로 답변하는 것이 필요하다.
- 하나님 앞에서 양심에 거리낌이 없는 자가 되기 위해 노력해야 한다. 마음으로 죄를 짓지 않기 위해 노력해야 하며, 마음으로 죄를 지었을 때 회개해야 한다. 양심에 거리끼는 것을 생각하고 그것을 행동으로 옮겨서는 안 된다. 죄된 생각이 떠오를 때 재빠르게 알아채고 생각을 전환해야 한다.
 
10. 영적터치(단어/구절)
- 16절 하나님과 사람에 대하여 항상 양심에 거리낌이 없기를 힘쓰나이다 

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-14', '사도행전', '24장 21절 ~ 27절', '율법보다 본성이 앞설 때에 느끼게 되는 두려움', '[행24:21-27]
21 오직 내가 그들 가운데 서서 외치기를 내가 죽은 자의 부활에 대하여 오늘 너희 앞에 심문을 받는다고 한 이 한 소리만 있을 따름이니이다 하니
22 벨릭스가 이 도에 관한 것을 더 자세히 아는 고로 연기하여 이르되 천부장 루시아가 내려오거든 너희 일을 처결하리라 하고
23 백부장에게 명하여 바울을 지키되 자유를 주고 그의 친구들이 그를 돌보아 주는 것을 금하지 말라 하니라
24 수일 후에 벨릭스가 그 아내 유대 여자 드루실라와 함께 와서 바울을 불러 그리스도 예수 믿는 도를 듣거늘
25 바울이 의와 절제와 장차 오는 심판을 강론하니 벨릭스가 두려워하여 대답하되 지금은 가라 내가 틈이 있으면 너를 부르리라 하고
26 동시에 또 바울에게서 돈을 받을까 바라는 고로 더 자주 불러 같이 이야기하더라
27 이태가 지난 후 보르기오 베스도가 벨릭스의 소임을 이어받으니 벨릭스가 유대인의 마음을 얻고자 하여 바울을 구류하여 두니라

