2023년 8월29일 사도행전 24장 21절~27절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-벨릭스(22,24,25,27절), 도(22,24절), 불러(24,25,26절)
4.주제만들기 : 율법보다 본성이 앞설 때에 느끼게 되는 두려움
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
-벨릭스는 바울을 즉시 판결하지 않고 자신의 곁에 둔다.
-바울에게 자유를 주고 친구들이 그를 돌보는 것을 금하지 말라 명한다.
-벨릭스는 아내와 함께 바울로부터 복음을 듣지만 두려움이 생겨 듣지 않는다.
-바울을 자주 불러 그와 이야기하며 바울로부터 돈을 받으려는 기대를 한다. 
- 벨릭스는 총독이 바뀌어도 유대인들의 환심을 사기 위해 지속해서 구류한다.
7.하나님 찾기 (해석) 
8.인간(해석):
-벨릭스는 율법에 대해 어느 정도 알고 있었을거라 생각된다. 그렇기 때문에 바울에 대해 판결했을 경우 나타날 수 있는 현상에 대해 우려했을거라 생각한다.
-벨릭스는 바울을 정치적으로 이용하기 위해 구류하기도 하고, 자신의 유익을 얻기 위해 구류하기도 했다.
-벨릭스는 율법을 알았기 때문에 바울이 전하는 복음과 의와 절제, 심판에 대해 들으니 두려움이 생겨 듣지 못한다. 
9. 적용(나): 
- 율법을 알고 있지만 자신의 본성에 타협하여 죄에서 벗어나지 못하면 두려움이 생긴다. 율법을 모른다면 자신의 행동이, 생각이 죄인지 모른다. 
- 율법을 아는 사람은 세상 탐욕과 욕심에 사로 잡혀 살지만 결국 그것이 죄인걸 깨닫는다. 이 때 돌이키거나 회피할 수 있는데 벨릭스는 옳은 말을 하는 바울이 두려웠을 것이다.
- 예수님을 통해 나의 죄성이 무엇인지, 무엇을 위해 살아야하는지 알 수 있다. 내 자아는 예수님의 사랑과 십자가로 인해 날마다 죽고 예수님만 바라는 삶을 위해 기도해야겠다. 문득 틔어나오는 내 죄성을 끊을 수 있길 소망한다. 
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-15', '사도행전', '25장 1절 ~ 10절', '제목 없음', '(사도행전 25장)
1.  베스도가 부임한 지 삼 일 후에 가이사랴에서 예루살렘으로 올라가니
2. 대제사장들과 유대인 중 높은 사람들이 바울을 고소할새
3. 베스도의 호의로 바울을 예루살렘으로 옮기기를 청하니 이는 길에 매복하였다가 그를 죽이고자 함이더라
4. 베스도가 대답하여 바울이 가이사랴에 구류된 것과 자기도 멀지 않아 떠나갈 것을 말하고
5. 또 이르되 너희 중 유력한 자들은 나와 함께 내려가서 그 사람에게 만일 옳지 아니한 일이 있거든 고발하라 하니라
6. 베스도가 그들 가운데서 팔 일 혹은 십 일을 지낸 후 가이사랴로 내려가서 이튿날 재판 자리에 앉고 바울을 데려오라 명하니
7. 그가 나오매 예루살렘에서 내려온 유대인들이 둘러서서 여러 가지 중대한 사건으로 고발하되 능히 증거를 대지 못한지라
8. 바울이 변명하여 이르되 유대인의 율법이나 성전이나 가이사에게나 내가 도무지 죄를 범하지 아니하였노라 하니
