5.하나님 찾기 (관찰)
- 

6.인간 찾기 (관찰)
- 유대인들의 주장이 사실이 아니면 그들에게 내줄 수 없음을 베스도에게 말하고 가이사에게 상소하는 바울 
- 가이사랴에 문안 온 아그립바 왕과 버니게에서 바울의 일을 말하는 베스도
- 유대인 대제사장들과 장로들이 바울을 고소하여 정죄하기를 청했으나 로마법에 맞지 않음으로 내주지 않았음을 말하는 베스도
- 로마법대로 재판을 열어 바울이 유대인들 앞에서 변명할 기회를 주었더니 유대인들이 악행에 대한 혐의는 하나도 제시하지 않고 유대교와 예수의 부활에 관한 일로 고발한 것이 전부였음을 말함.

7.하나님 찾기 (해석) 
- 로마에 가서 복음을 전하라 명령하신 성령님이 로마로 복음을 전하러 가는 바울을 보호하는데 로마인을 사용하심. 벨릭스나 베스도는 자신이 하나님께 쓰임 받고 있다는 것을 알지 못할 것임. 하나님의 섭리는 참으로 놀라움.

8.인간(해석):
- 예루살렘에는 이미 복음을 전하였고, 로마에 가서 복음을 전하라는 예수님의 명령을 완수하고자 가이사에게 상소를 받겠다고 말하는 바울. 자신의 무죄를 증명하는 것보다 복음 전파가 우선이었던 것을 볼 수 있다.
- 로마법을 준수한 총독 베스도. 만약 유대인의 환심을 사고 싶었던 베스도가 로마법까지 준수하지 않았다면, 바울을 유대인들에게 내주었을 것이며, 바울이 유대인에게 정죄를 받았다면, 바울은 목숨을 잃었을 것이다.
- 바울을 향한 유대인의 고소가 베스도에게는 의문이었을 것임.
- 이들은 이해하지 못하지만, 이 모든 사건을 통해 복음이 로마까지 전파되는 과정이 된다.

9. 적용(나): 
- 모든 정신이 예수님의 명령에 집중된 바울을 본받아야 한다. 사명을 향해 나아갈 때 여러 가지 상황들과 주변인들이 나를, 내 심령을 괴롭게 할 때가 있다. 그것들에 의연해야 한다. 하나님은 그 상황들까지 이용하셔서 내게 주신 사명을 이루어 가신다. 내 감정, 의지, 능력은 아무것도 아니다. 주신 사명은 사명자가 이루는 것이 아니라 하나님께서 이루시는 것임을 기억해야 한다. 내 기분 내 상태는 중요한 것이 아니다. 장차 이루어질 주님의 꿈을 바라보며 한 걸음 한 걸음 묵묵히 걸어가야 한다. 

10. 영적터치(단어/구절)  
11절 내가 가이사께 상소하노라

11. 믿음과 회개 및 감사기도로 마무리
