8. 인간 찾기 (해석)
분봉왕 아그립바 앞에서 심문받는 바울은 그러한 긴장감이 맴도는 위기의 시간을 도리어  복음 전하는 복음의 기회로 삼는다.
침착 하면서도 열정적으로 자신이 예수 만나기 전 어떠한 신분 이었으며 그리스도인들 을 핍박하는 사람 이었는지 증언하고 있다.
이 모습은 마치 자신의 과거 모습을 들추는 동시에 현재 왕의 신분이지만 주님을 만나지 못한 한 불쌍한 영혼을 마음에 두고 호소하는 느낌을 갖게만든다.

9. 적용(나)
예수 믿기 전 의 나의 모습을 늘 상고하며 늘 주님앞에서 감사와 겸손한 모습으로 살아야겠다. 불신자들을 늘 긍휼함과 안타까운 마음으로 복음을 지혜롭게 잘 전달해야겠다 

