4. 주제 만들기
아그립바 왕 에게 간증 하는 바울

5.하나님 찾기(관찰)
핍박하는 바울에게 나타나신 예수(간증 중)

6.인간 찾기(관찰)
아그립바 분봉왕 에게 자신이 어떻게 예수를 믿게됬는지 증거하는 바울
7.하나님 찾기(해석)

8. 인간 찾기 (해석)
예수믿고 사명자가 된 바울.
예수 믿기전 그리스도인 들을 핍박하기에 누구보다 앞장섰던 바울.
이제는 예수님의 진리를 만난 자신을 향하여 핍박하는 같은민족 유대인들과 종교 지도자들. 이젠 입장이 바뀐 자신을 보면서 바울은 스스로를 향하여 과거에 영적무지한자요 사탄의 속한자의 모습을 되새겼을 것이다. 실제로 다른 성경에서 그의 회개의 고백을 볼수있다.
이 모든것을 아직 주님을 만난 경험이 없는 아그립바 왕 에게 호소하고 있다.

9. 적용(나)
아무리 하나님일에 대하여 큰 열정이 있다고 하더라도, 방향을 잘못 설정하면 오히려 주님의 비전에 큰 해악을 저지를수있는 사람이 될수있음을 본다. 때로는 사역 속도가 조금 늦더라도 영적좌표를 정검하고 재정비  하는것이 더욱 중요하다 여겨진다.
사탄의 도구였던 사울청년이 다메섹에서 예수믿고 주님의 큰 일꾼이 된것은, 열정의 방향을 틀어주신 주님의 전적인 은혜임을 믿는다.
나 또한 산기도를 통한 주님의 음성 듣는것을 무엇보다 우선순위 로 여겨아겠다.

