2023년 9월 4일 사도행전 26장 21~30절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
바울: 24(2), 25, 28, 29
베스도: 24, 25
왕: 26, 27, 30
아그립바: 27, 28

4.주제 만들기: 참되고 온전한 말, 예수는 그리스도.

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 유대인들이 죽이려고 했으나 하나님의 도우심으로 살아있는 바울
- 유대인과 이방인들 그리고 총독과 왕 앞에서도 복음을 전하는 바울
- 유대인들이 자신을 정죄하려 하나 선지자들과 모세가 한 말을 전하는 것뿐이고 그것은 그리스도가 고난을 받으실 것과 죽은 자 가운데서 먼저 다시 살아나사 이스라엘과 이방인들에게 빛을 전할 것이라 한 것이다.
- 바울이 제정신이 아니라고 말하는 베스도, 자신은 미친 것이 아니라 참되고 온전한 말을 한 것이라고 말하는 바울
- 아그립바왕에게 선지자를 믿느냐고 묻는 바울
- 바울에게 적은 말로 그리스도인이 되게 하려 한다고 말하는 아그립바왕
- 이렇게 결박된 것 외에는 자기와 같이 되기를 원한다고 말하는 바울 

7.하나님 찾기 (해석) 

8.인간(해석): 
- 유대인의 핍박을 받아온 바울이 살아있는 것도 총독과 왕 앞에서 복음을 전하는 것도 모두 하나님께서 도우셨기 때문이다. 
- 바울은 구약의 말씀으로 예수님의 십자가와 부활, 그리고 구원에 대해서 증언함.
- 베스도가 듣기에는 바울이 미친 것으로 보임. 
- 바울은 자신이 한 말은 참되고 온전한 말임을 담담히 말함.
- 그리고 아그립바왕에게 도전함. 성경을 믿고 지금 일어나고 있는 일들에 대해서 다 알고 있는 아그립바에게 복음이 깨달아 지는지 확인하고 있음.
- 네가 적은 말로 나를 그리스도인이 되게 하려 한다고 말하는 아그립바왕에게 말이 많고 적은 것이 중요한 것은 아니다. 이렇게 결박된 것 외에는 다 자기와 같이 되기를 원한다라고 말하는 바울. 
비록 붙잡혀 묶여 있으나 예수님을 만난 기쁨과 복음을 전하는 기쁨이 충만하여 모두가 자기와 같은 상태가 되기를 바라는 것이다. 즉, 예수님을 만나 구원받고 예수님과 함께 살아가는 벅찬 감격과 기쁨을 누리길 원하는 것이다.

9. 적용(나): 
“예수는 그리스도.” “참되고 온전한 말.” 복음을 어떻게 전할까 고민하던 중 사도행전을 읽고 깨달아 단순하지만 강력하게 복음을 전하는 말로 위 문장을 선택했었다. 그리고 이 문장을 카카오톡 인사말로 올려놓았고 그렇게한지도 어느덧 10년이 다 되어간다. 
나는 지금 이 문장을 삶 속에서 얼마나 말하고 있는가. SNS에 올려놓고 끝은 아닌가? 가끔 이게 무슨 뜻이냐고 물어오는 사람에게 설명하는 것이 끝은 아닌가? 생각해 본다. 

10여 년 전 청년들 앞에서 “내가 백수인 것을 제외하고 여러분이 다 나와 같이 되기를 원한다.”고 바울을 흉내 내며 외쳤던 나는 그 이후 왜 멈춰있는가? 다시 시작해야 한다.

복음을 담대하고 단순하게 전하되, 비방하는 사람들에게 “이 말은 참되고 온전한 말입니다.” 라고 담백하게 말하는 삶을 살아야 한다.
그리고 “나는 보잘것없는 사람이지만 예수님을 만나고 동행하기에 기쁨이 넘친다. 너무나 행복하다. 너희도 나와 같이 되길 바란다.”라고 말할 줄 알아야 한다.

10. 영적터치(단어/구절)  
25 내가 미친 것이 아니요 참되고 온전한 말을 하나이다
29 이렇게 결박된 것 외에는 나와 같이 되기를 하나님께 원하나이다

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-08-21', '사도행전', '27장 1절 ~ 10절', '복음을 전할 때 생기는 수많은 고비', '행27:1-10]
1 우리가 배를 타고 이달리야에 가기로 작정되매 바울과 다른 죄수 몇 사람을 아구스도대의 백부장 율리오란 사람에게 맡기니
2 아시아 해변 각처로 가려 하는 아드라뭇데노 배에 우리가 올라 항해할새 마게도냐의 데살로니가 사람 아리스다고도 함께 하니라
3 이튿날 시돈에 대니 율리오가 바울을 친절히 대하여 친구들에게 가서 대접 받기를 허락하더니
4 또 거기서 우리가 떠나가다가 맞바람을 피하여 구브로 해안을 의지하고 항해하여
5 길리기아와 밤빌리아 바다를 건너 루기아의 무라 시에 이르러
6 거기서 백부장이 이달리야로 가려 하는 알렉산드리아 배를 만나 우리를 오르게 하니
7 배가 더디 가 여러 날 만에 간신히 니도 맞은편에 이르러 풍세가 더 허락하지 아니하므로 살모네 앞을 지나 그레데 해안을 바람막이로 항해하여
8 간신히 그 연안을 지나 미항이라는 곳에 이르니 라새아 시에서 가깝더라
9 여러 날이 걸려 금식하는 절기가 이미 지났으므로 항해하기가 위태한지라 바울이 그들을 권하여
10 말하되 여러분이여 내가 보니 이번 항해가 하물과 배만 아니라 우리 생명에도 타격과 많은 손해를 끼치리라 하되

