6.인간 찾기 (관찰)
- 광풍속에서 굶주리고 두려워하는 사람들, 그리고 이들에게 하나님께서 안전을 지켜주실 것이라고 말하는 바울
- 도망가려고 거룻배를 바다에 내려놓는 사공들

7.하나님 찾기(해석)

8. 인간(해석)
- 광풍 속에서 바닷물이 배를 쳐서 배는 심하게 흔들리고 배 안으로 파도가 들이쳐 온몸으로 물을 받아내며 버텨야 했을 것이다. 그리고 살기 위해 배에 고인 물을 퍼내거나 배의 시설들이 부셔지는 막기 위해 혼신의 힘을 다해야 했을 것이다. 그런데 먹을 것이 없어 굶주리기까지 했으니 배에 탄 사람들 모두 살 가망이 없다고 생각했을 것이다.
- 똑같은 상황을 겪고 있는 바울은 몸은 힘들지만 모두 무사할 것이라는 확신이 있었다. 왜냐하면 하나님의 사자로부터 네가 가이사에게 갈 때까지 안전할 것이고 배에 탄 모든 사람도 안전할 것이라는 하나님의 말씀을 들었기 때문이다.
- 내게 말씀하신 그대로 되리라고 하나님을 믿노라 고백하는 바울. 하나님의 전능하심을 믿는 자는 하나님의 말씀이 그대로 이루어질 것을 알고 믿는다. 바울은 하나님의 전능하심을 확실히 믿었다.
- 배에 탄 자들을 안심시키는 바울. 하나님의 말씀을 듣고 이루어지는 것을 지켜볼 수도 있으나 바울은 두려워 떠는 사람들을 안심시키기 위해 하나님의 말씀을 전하고 안심시킨다. 그들을 사랑하기 때문이고, 하나님의 역사하심을 알리기 위해서다. 이것은 최소한 세 가지 효과가 있다. 첫째, 사람들에게 조금이나마 살 소망을 갖게 하는 것이고. 둘째, 극한의 상황에서 하나님을 생각하고 기도하게 하는 것이고. 셋째, 일이 이루어졌을 때 하나님이 하셨음을 확실히 알게하는 것이다. 하나님이 하신 말씀을 미리 알리지 않았다면 일이 이루어진 다음 그들에게 “사실 하나님이 지켜주실 거라고 몇 일전에 말씀했었다.”라고 하면 그들은 정말 그랬나? 하고 반신반의할 수도 믿을 수도 또는 웃기는 소리라고 생각할 수 있다.

9. 적용(나)
- 사명을 향해 나아갈 때 쉬지 않고 기도하며 주님의 음성을 들어야 한다.
- 하나님의 전능하심을 확실히 믿어야 한다. 내 속에 부분적으로 하나님을 제한하고 있는 부분이 있을 것이다. 그것을 깨야한다.
- 하나님이 이루어질 일에 대해 말씀하시면 함께 하는 사람들에게 듣는 사람들에게 선포해야 한다. 조용히 간직하는 것이 겸손이고 미덕인 줄 착각하면 안 된다는 것을 깨달았다. 
- 듣는 사람의 마음의 안정과 함께하는 사람들이 하나님을 바라보게 함과 일이 일어난 후 하나님께 확실한 영광을 돌릴 수 있도록 하나님이 해 주신 말씀은 선포해야 한다.
 
