본문에 다양한 모습의 ''구윈''이라는 단어가 사용되고있다. 선장과 사공이나 백부장이나 군인들도 생사를 앞둔 위기 앞에서는 동등한 약한 존재들이다. 한편 하나님의 구원의 예언을 이미 전달받은 바울만 의연하다. 그러한 바울을 붙잡기 위하여 노력하는 백부장의 모습이 간절해 보인다.

