독사에 물린후 해를 받지않은 바울
이를 본 원주민들은 그를 신이라 생각함
추장 보브리오 아버지의 병을 고치는 바울

7.하나님 찾기(해석)
큰 풍랑을 만나 배가 깨짐을 받아 간신히 구사일생으로 살아난 사람들은 멜리데 섬에 표류한다. 그곳에서 원주민 들 로부터 섬김을 받는다. 독사에 물린후 해를 받지않은 바울. 그 바울은 추장 아버지를 고치는등 하나님은 바울에게 능력을 행하게 하신다. 
한시라도 빨리 로마로 가야될듯 한데 하나님은 시간을 지체시키며 왜  섬 에 머무루게 하셨을까?
답은 간단하다. 하나님은 바울을 통하여 그 문명이 발달하지 못한 멜리데 섬 사람들의 영혼구원을 간절히 원하셨을것이다.
세계선교 복음화에 가장 열정을 가지신분은 하나님 이시다.

