9. 적용(나)
당장 현실적으로 바쁘고 힘든 일이 있더라도 약속의 말씀을 붙잡고 견딘다면 희망의 멜리데섬을 만날것을 깨우친다. 언제나 큰 그림을 그리고 나에게 사명자의 길을 인도하시는 주님을 찬양합니다!! 더욱
영혼구원 하는 일에 더욱 열정을 가져야겠다.

