4. 주제 만들기 
로마에서 담대히 복음을 전파하는 바울

5.하나님 찾기(관찰)

6.인간 찾기(관찰)
로마 안에 사는 유력한 유대인들은 스스로가 복음을 들은적이 없다고 함
그 유대인들은 바울에게 복음전파의 기회를 줌
복음을 듣고 믿는 자도 있고 믿지않는 자들도 있음
계속해서 이방인들 에게도 담대하게 복음을 전파하는 바울

7.하나님 찾기 (해석)

8. 인간 찾기 (해석)
사도행전의 저자인 누가는 사도행전 을 마무리하는 제일 마지막 28장31절에 "담대하게 거침없이 가르치더라" 기록 하였다
바울이 최종 목적지인 로마에 오면 그의 생명도 큰 위협을 받을것을 알면서 전파할수 있었던 용기는 어디에서 왔을까? 로마에 오기전에  큰 풍랑을 만났을때 이미 하나님은 그의 사자를 바울에게 보내어 큰 위로를 주셨다.  뿐만 아나라 믿음의 형제들이 바울을 찾아와 큰 용기를 주었다. 그 힘과 용기로 바울은 로마 안에서도 복음을 담대하게 거침없이 전파하였다. 선교는 결국순종하는 자를 사용하시는 하나님이 이루어 나가심을 본다. 
한편 복음을 한번도 들어보지 못한 로마안에  거주하는 유력 유대인들중 바울이 전하는 복음을 받은후에 믿는자들과 믿지 않는자들로 나뉜다. 덕분에 복음은 대한민국을 포함한 이방민족에게 더욱 급하게 퍼저나가고 있다.  영혼을 사랑하사쉬지않으시는 하나님의 열정의 표시인 복음전파에 참여하는 모든사람들은 이미 복을 받았고 바울처럼 승리자이다.

9. 적용(나)
예수와 그의 비전을 심하게 방해했던 영적으로 무지하였던  바울을 변화시키시어 결국 로마에 이르기까지 복음을 전파케하시는 주님의 인도하심과  역사하심을 본다. 무엇보다 모든 사람들이 예수믿고 구원 받기를 간절히 원하시는 사랑의 본체이신 예수.
나도 주님의 심장을 가지고 바울처럼 복음전파에 있어서 더욱 거침없이 가르치고 전하는 종이 되야겠다.
10. 영적 터치(단어/구절)
31절: 담대하게 거침없이 가르치더라

11. 믿음과 회개 및 감사기도로 마무리
