8. 인간 찾기 (해석)
"의인은 믿음으로 말미암아 살리라" 이 말씀은 어쩌면 복음을 이해하고 받아들임에 있어 가장 핵심구절  일것이다. 우리가 구원을 받는 조건은 우리의 행위가 아닌  오직우리를 위하여 독생자예수를 십자가에서 죽음로 내어주신 무궁하신 하나님의 사랑과 은혜임이 절대적이다.  
이 진리의 복음을 로마에 있는 모든 지체들과 모든 사람들에게 전하는 목적은 그들의 믿음이 더욱 견고해 지기를 원해서이다. 또한 복음을 전하는 바울은 매우 겸손한 마음의 상태인것을 알수있다. 스스로를 헬라인 이나 야마인이나 지혜로운자나 어리석은 자들에게 빚을졌다고 기록한것을 보면알수있다.  복음 전파자는 낮은 자세로 또한 섬김의 태도로 진리를 선포하는 모습은 모범적인 일꾼의 모습임을 보여준다.

9. 적용(나)
