4.주제 만들기: 

5.하나님 찾기 (관찰)
- 자신을 거부하는 자들을 마음의 정욕대로 더러움에 내버려 두심.
- 그들을 상실한 마음대로 내버려 두사 합당하지 못한 일을 하게 하심.

6.인간 찾기 (관찰)
- 하나님을 알지만 우상을 숭배하는 사람들
- 여자들이 순리로 쓸 것을 역리로 씀.
- 남자들이 음욕으로 불 붙어 남자가 남자와 더불어 부끄러운 일을 행함.
- 사형에 해당하는 일(해서는 안 되는 일)인 줄 알면서도 그 일 행하고, 또 더 나아가 그런 일을 행하는 자들을 옳다고 말함.

7.하나님 찾기 (해석) 
- 하나님을 알면서도 하나님을 거부하는 자들을 하나님은 그 상태로 내버려두심. 
- 그러나 하나님은 한 번씩 빛을 비추심. 

8.인간(해석)
- 하나님을 알지만 하나님이 아니라 우상을 숭배하는 이유는 그들이 마음의 정욕을 이루고자 하기 때문이다.
- 남자가 남자와 더불어 부끄러운 일을 행했는데, 이것이 그들의 그릇됨에 상당한 보응의 역할이 됨. 이러한 부끄러운 상태 자체가 벌이고 이러한 인생 자체가 괴로움과 고통의 인생임.
- 하나님은 빛을 비추시지만, 그들은 그 빛을 한 번씩 느끼면서도 자신의 쾌락을 위해 하나님을 거부하는 것임.
- 그들이 마음에 하나님 두기를 싫어하는데 그것은 합당하지 못한 일을 원하고 바라고 그것을 통해 만족을 누리기 때문임.
- 그 같은 일은 사형에 해당하는 줄 알면서도 지속하고 그런 일 하는 자들을 옹호하는 이유는 다 같이 그런 일을 즐기기 위함이요, 자기 합리화요, 나아가 양심에 화인을 맞아 잘못된 일인지도 모르게 된 것이다.   

9. 적용(나): 
- 세상에는 특히 교회에는 다 나보다 나은 사람들, 선한 사람들, 믿음 좋은 사람들만 있다고 생각했다. 그러나 어른이 되어가면서, 그리고 믿음이 깊어지면서 그렇지 않다는 것을 알게 되었다. 나보다 남을 낫게 여기지 않아서가 아니라, 정말 그렇다는 것을 알게 되었다. 
- 교회에도 하나님의 말씀대로 사는 것을 거부하고 자유롭게 살아가길 원하는 사람들이 꽤나 있다. 그러면서 그것을 자유함이라고 말하는 교인들도 있다. 
- ‘너희는 자유가 있으나 그 자유로 악을 가리는데 쓰지 말고, 오직 하나님의 영과 같이 하라’  벧전 2:16
- 불신자들과 믿는다고 말하지만 믿음 없는 자들을 대할 때 어떻게 대해야 하는가 어려움이 많지만, 그저 하나님께서 빛을 계속 비추시듯 나는 그들에게 선한 마음과 태도로 일관하며 복음의 전진기지 역할을 지속해야 한다고 생각한다. 그들이 언제 어떻게 주님의 비추심을 받아들이고 하나님께 돌아올지는 아무도 모르기 때문이다. 
- 마음의 정욕대로 행하는 자를 내버려 두시고 심판하시는 이는 하나님이요. 나는 마지막 날 누가 양이 되고 누가 염소가 될지 전혀 모르기 때문이다. 

10. 영적터치(단어/구절)  

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-01', '로마서', '2장 1절 ~ 10절', '제목 없음', '1.  그러므로 남을 판단하는 사람아, 누구를 막론하고 네가 핑계하지 못할 것은 남을 판단하는 것으로 네가 너를 정죄함이니 판단하는 네가 같은 일을 행함이니라
2. 이런 일을 행하는 자에게 하나님의 심판이 진리대로 되는 줄 우리가 아노라
3. 이런 일을 행하는 자를 판단하고도 같은 일을 행하는 사람아, 네가 하나님의 심판을 피할 줄로 생각하느냐
4. 혹 네가 하나님의 인자하심이 너를 인도하여 회개하게 하심을 알지 못하여 그의 인자하심과 용납하심과 길이 참으심이 풍성함을 멸시하느냐
5. 다만 네 고집과 회개하지 아니한 마음을 따라 진노의 날 곧 하나님의 의로우신 심판이 나타나는 그 날에 임할 진노를 네게 쌓는도다
6. 하나님께서 각 사람에게 그 행한 대로 보응하시되
7. 참고 선을 행하여 영광과 존귀와 썩지 아니함을 구하는 자에게는 영생으로 하시고
8. 오직 당을 지어 진리를 따르지 아니하고 불의를 따르는 자에게는 진노와 분노로 하시리라
9. 악을 행하는 각 사람의 영에는 환난과 곤고가 있으리니 먼저는 유대인에게요 그리고 헬라인에게며
10. 선을 행하는 각 사람에게는 영광과 존귀와 평강이 있으리니 먼저는 유대인에게요 그리고 헬라인에게라

