헁함: 1절 3절 6절 7절 10절

4. 주제 만들기 
불의한 자를 심판 하시는 하나님

5.하나님 찾기(관찰)
심판자 이신 하나님 
보응 하시는 하나님
영생을 주시는 하나님 

6.인간 찾기(관찰)
남을 판단하는 사람들
불의를 행하는 사람
불의한 자들의 최후
참고 선을 행하는 자들이 받는 복

7.하나님 찾기(해석)
하나님은 모든 사람들이 서로 사랑하고 살기를 원하신다. 2장1절 "그러므로"는 1장에 나오는 "스스로 지혜롭게"를 받치고 있는 의미로 스스로 높게 여기는 자는 불의를 행하는 자이며 특징으로는 다른 사람들을 판단하는 죄를 범한다. 만약 회개하지 않으면 하나님은 이들을 마지막에 심판하신다.

8. 인간 찾기 (해석)
감사와 겸손은 그리스도인 에게는 선택이 아닌 필연적으로 갖추어야될 덕목이다. 그렇지 않으면 평상시 다른사람을 쉽게 무시하고 판단하는 불의를 저지를수 있음을 보여준다. 반대로 오래참고 다른 영혼을 돌보고 선을 행한다면 하나님의 평강과 영생의 기쁨이 주어진다.

9. 적용(나)
주변 영혼들을 귀히 여기는 마음을 더욱 기져야겠다

10. 영적 터치(단어/구절)
10절: 선을 행하는 각 사람에게는 영광과 존귀와 평강이 있으리니

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-02', '로마서', '2장 11절 ~ 20절', '제목 없음', '11. 이는 하나님께서 외모로 사람을 취하지 아니하심이라
12. 무릇 율법 없이 범죄한 자는 또한 율법 없이 망하고 무릇 율법이 있고 범죄한 자는 율법으로 말미암아 심판을 받으리라
13. 하나님 앞에서는 율법을 듣는 자가 의인이 아니요 오직 율법을 행하는 자라야 의롭다 하심을 얻으리니
14. (율법 없는 이방인이 본성으로 율법의 일을 행할 때에는 이 사람은 율법이 없어도 자기가 자기에게 율법이 되나니
15. 이런 이들은 그 양심이 증거가 되어 그 생각들이 서로 혹은 고발하며 혹은 변명하여 그 마음에 새긴 율법의 행위를 나타내느니라)
16. 곧 나의 복음에 이른 바와 같이 하나님이 예수 그리스도로 말미암아 사람들의 은밀한 것을 심판하시는 그 날이라
17.  유대인이라 불리는 네가 율법을 의지하며 하나님을 자랑하며
18. 율법의 교훈을 받아 하나님의 뜻을 알고 지극히 선한 것을 분간하며
19. 맹인의 길을 인도하는 자요 어둠에 있는 자의 빛이요
20. 율법에 있는 지식과 진리의 모본을 가진 자로서 어리석은 자의 교사요 어린 아이의 선생이라고 스스로 믿으니

