율법의 완성은 오직 예수그리스도를 통해서 이루어짐을 바울은 가르친다. 비록 하나님이 유대인들의 조상 모세를 통하여 율법을 허락하였지만, 그 받은 율법을 주신 하나님의 뜻을 모르고 스스로 높아짐의 도구로 사용한다면 영적 맹인의 길을 인도하는 범죄자가 되는것이다.

