율법에 대하여 무지한 사람들

7.하나님 찾기(해석)


8. 인간 찾기 (해석)
율법은 어떤 사람이나 특정한 민족의 자랑의 산물로 삼으면 뜻에 불일치 된다고 바울은 주장하고 있다. 한 예로, 바울은 유대인들의 대표적 율법  행뮈인 ''할례'' 를  들었다. 할례의식을  중요시 여기는 유대인들은  스스로 율법 받은것을 다른 민족들과 구분해서 큰 자부심과 자랑거리로 여기었다. 하지만 바울은 이 사상은 주님의 뜻과 배치되는 생각이라 말하고 있다. 유대인의 할례는 남에게 보이기 위한  스스로의 칭찬받기 목적이 아닌 도리어 마음에 하라고 말한다. 즉 울법을 대하는 인간의 태도는 스스로를 높이기위함이 아니라 하나님의 영광을 드러내기  위함이라 가르치고 있는 것이다.

9. 적용(나)
하나님 말씀을 아는 만큼  더욱 겸손하며 하나님을 높이는 데 힘써야겠다.

10. 영적 터치(단어/구절)
그 칭찬이 사람에게서가 아니요  다만 하나님에게서니라

