4.주제 만들기: 우리를 의롭다 칭하시므로 자신의 의로우심을 나타내시는 하나님

5.하나님 찾기 (관찰)
- 하나님의 의로우심

6.인간 찾기 (관찰)
- 유대인과 할례받은 자에게 주어진 유익
- 그러나 하나님의 말씀을 믿지 않는 자가 있다.
- 죄 아래에 있는 유대인과 헬라인

7.하나님 찾기 (해석) 

8.인간(해석): 
- 유대인과 할례의 의미에 주어진 대로 하지 않으면 유익이 없다. 그러나 그것이 주어진 대에는 범사에 유익이 많다.
- 인간이 믿지 않았을 뿐, 하나님은 미쁘심. 그의 계획을 이루어 가실 것이다.
- 인간은 불의하지만 인간의 불의를 용서하시고 의롭다 칭하시는 하나님의 의로우심이 나타남.
- 이 하나님이 의로우시기 때문에 심판의 이유가 충분함.
- 거짓으로 하나님의 의가 드러나시면 나의 거짓으로 하나님의 의로우심과 영광스러움이 나타나는 것이다. 그러나 그런데도 우리가 그것을 위해 악한 행위를 해서는 안 된다.
- 유대인과 헬라인, 모든 인간은 죄 아래에 있다.
- 시편에 기록된 바 의인은 없나니 하나도 없으며. 하나님이 땅을 굽어살피시며 의인을 찾으시나 한 사람도 찾지 못하셨다.

9. 적용(나): 
- 의로우신 하나님께서 불의한 나를 의롭다 칭해주시는 것에 감사하며 겸손하게 살아야 한다.
- 나는 의롭다고 착각하면 안 된다. 나는 의롭지 못하고 거룩하지 못한 사람이다. 이것을 기억하고 주님께 감사하며 겸손하게 살아야 한다. 
- 먼저는 하나님 앞에 겸손이요, 나아가서 사람 앞에서도 겸손해야 한다. 나는 하나님께 빚진 자요, 모든 이들에게 빚진 자이기 때문이다.
- 하나님께서 열매를 풍성하게 맺게 해주실 때 “내가 한 역할했어요.”라고 교만을 떨어서는 안 된다. 내가 이런 교만을 떨면 기뻐하시는 이는 하나님이 아니요, 사탄이 될 것이다.


10. 영적터치(단어/구절)  
