- 바울은
- 의인은 하나도 없고 깨닫는 자도 없고, 하나님을 찾는 자도 없고 모두 다른 곳으로 치우쳐 무익하게 되었으며 선을 행하는 자가 없고 하나도 없다.
- 그들의 목구멍은 열려있는 무덤이고 혀로는 거짓말을 일삼으며 입술에는 독사의 독이 있다. 그들의 입에는 저주와 악독이 가득하다.
- 그들의 발은 피 흘리는데 빠르며 그들의 길에는 파멸과 고생이 있어 평강의 길을 알지 못한다. 
- 그들의 눈에는 하나님에 대한 두려움이 없다고 말하며 율법이 말하는 것은 율법 아래 있는 자들에게 말하는 것이라고 말한다. 그것은 모든 입을 다물게 하고 온 세상이 하나님의 심판 아래 있게 하려는 것이며 율법의 행위로는 의롭다 인정 받을 육체가 없고 율법으로는 죄를 깨달을 뿐이라고 말한다. 
7.하나님 찾기 (해석) 
8.인간(해석):
-바울은 율법을 제대로 안다면 율법 위에 계신 분은 오직 하나님이시고 율법이 우리에게 주는 참된 의미를 알아야 한다고 말한다. 율법을 행위로만 이해하고 행동하면 하나님을 알지 못하며 오히려 하나님에게 벗어나 다른 사람을 정죄하는 교만과 오만함에 빠져든다고 경고한다. 율법을 제대로 깨달으면 자신의 죄를 깨닫게 되고 겸손하게 되며 의의 길로 들어갈 수 있음을 말한다.  
9. 적용(나):
- 최근 박영선 목사님께서 술과 담배, 새벽예배에 대해 말씀하신 영상을 보았다. 술과 담배를 성경에서 금하지 않지만 우리나라에선 교회를 다니는 사람들이 가지는 특권이라고 인식하는 경우가 많다고 한다. 그것은 좋은 현상일 수 있지만 술과 담배를 하는 사람들을 정죄하는 도구로 사용되어서는 안된다고 말씀하셨다. 
- 사도 바울 시대에 유대인들은 성경을 볼 수 있는 특권을 가졌다. 그런데 유대인들이 가진 특권을 자신들을 드러내고 우월하다고 보이는데 사용했다. 성경의 말씀을 가지고 사람들을 정죄했고 교만했다. 사울은 그런 점을 지적하며 성경을 안다면 자신의 죄를 깨달아야 한다고 말한다. 마치 내가 조금이라도 영적으로 하나님과 친밀해지면 여지없이 내 안에 들어오는 교만함을 이야기하는 것 같다. 스스로 겸손해질 수 없는 존재이므로 하나님께 겸손함을 간절히 구해야겠다. 
- 자기 주장이 강한 편이라 주변의 조언을 무시하는 경우가 많은데 겸손하게 경청하고 받아들여야겠다.
