3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2023년 9월22일 로마서 4장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
-할례(11,12절), 무할례(11,12절), 아브라함(12,13,16,18절), 믿음(11,12,13,14,16,19절), 조상(12,16,17절), 후손(13,16,18절)
4.주제만들기
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
-바울은 율법보다 믿음이 중요함을 강조함
-아브라함은 소망이 없는 가운데도 믿음으로 많은 민족의 조상이 되었고 하나님께 영광을 돌렸다고 말함
7.하나님 찾기 (해석) 
8.인간(해석):
-바울은 예수님을 만난 후 과거에서 현재까지 이어진 잘못된 율법 의식, 우월주의 등을 알려주고자 했다. 아브라함의 이야기를 예로 들며 할례를 받아서 복을 받았거나 의로움이 이루어진게 아니라 할례 이전에 아브라함이 가졌던 믿음으로 인해 할례는 믿음을 확증한 것인라고 말하였다. 
- 율법주의 강하게 비판하였는데 믿음이 없이 율법만 따른다면 율법으로 인해 진노를 부른다고 말하였다. 오죽하면 율법이 없는 곳엔 범법함도 없다고 표현할 정도였다. 바울은 율법보다 중요한 하나님을 사랑하고 예수님을 인정하는 믿음을 강조하였다. 
9. 적용(나): 
- 현재 내 상황은 아브라함처럼 소망이 없는 상태이다. 가정에서 영적인 대화를 하기 힘들고 하나님으로 인해 위로와 희망을 보기 어려울 정도로 가족들은 영적인 피폐함을 경험하고 있다. 모든 것은 나의 잘못이다. 내가 믿음으로 중심을 잘 잡았다면 이런 상황은 발생하지 않았을 것이다. 아브라함과 같은 믿음이 내게 필요하다.
- 하나님께서 꾸준히 요구하신건 하나님을 향한 순종이었다. 매번 무너졌고, 알면서 무시했고, 죄의 유혹을 경험한 탓에 죄의 유혹에 너무 쉽게 무너지는 내 연약함으로 인해 그 쉬운 순종을 하지 못했다. 이제는 다시 일어서야할 때이고 아브라함과 같이 소망없는 때에 하나님을 믿는 믿음으로 버틴 것을 나도 해내고 싶다.
- 하나님께서 죄인이었던 나를 은혜로 만나주셨고 새롭게 하신 그 때처럼, 하나님을 간절히 소망하고, 하나님과 교제를 행복해하는 내가 되었음 좋겠다. 반드시 그렇게 회복 될 것을 확신한다.
10. 영적터치(단어/구절)
-아브라함이 바랄 수 없는 중에 바라고 믿었으니
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-09', '로마서', '4장 21절 ~ 25절', '제목 없음', '(로마서 4장)
21. 약속하신 그것을 또한 능히 이루실 줄을 확신하였으니
22. 그러므로 그것이 그에게 의로 여겨졌느니라
23. 그에게 의로 여겨졌다 기록된 것은 아브라함만 위한 것이 아니요
24. 의로 여기심을 받을 우리도 위함이니 곧 예수 우리 주를 죽은 자 가운데서 살리신 이를 믿는 자니라
25. 예수는 우리가 범죄한 것 때문에 내줌이 되고 또한 우리를 의롭다 하시기 위하여 살아나셨느니라

