7.하나님 찾기(해석)
 누구든지 예수를 믿기만 한다면 그가 설령 죽었던 죄인이라 할지라도 의릅게 여기사 다시 살려주시는 예수. 
그는 먼저 죽음에서 다시 살아나심을 우리에게 보여주심으로 믿음의 소망어 기준을 만들어 주셨다.
100세 나이의 아브라함 이나 그의 아내 사라 는 이미 생리적으로 태가 죽었음에도 다시 태가 다시 살아나서 이삭을 얻은 것처럼, 이를 통하여 변함없이 사망에서 생명으로 인도하시는 생명의 주님을 우리에게 보여주신다. 이것을 진심으로 믿는자는 누구나 구원을 받고 다시 태어난다. 죽었던 육도 다시 삶을 얻는것처럼 영도 거듭난다. 

8. 인간 찾기 (해석)


9. 적용(나)
영 육이 주님의 은혜로 다시 소망을 갖는것을 믿는다. 뿐만아니라 삶 가운데 소망하는 불가능해 보이는 일이 있더라도 주님이 역사 하시면 가능하게 될줄믿는다.  새로운 소망과 생명을 주시는 주닝을 더욱 의지해야겠다.

10. 영적 터치(단어/구절)
24절: 죽은 자 가운데서 살리신 이를믿는 자니라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-09-10', '로마서', '5장 1절 ~ 10절', '제목 없음', '(로마서 5장)
1. 그러므로 우리가 믿음으로 의롭다 하심을 받았으니 우리 주 예수 그리스도로 말미암아 하나님과 화평을 누리자
2. 또한 그로 말미암아 우리가 믿음으로 서 있는 이 은혜에 들어감을 얻었으며 하나님의 영광을 바라고 즐거워하느니라
3. 다만 이뿐 아니라 우리가 환난 중에도 즐거워하나니 이는 환난은 인내를,
4. 인내는 연단을, 연단은 소망을 이루는 줄 앎이로다
5. 소망이 우리를 부끄럽게 하지 아니함은 우리에게 주신 성령으로 말미암아 하나님의 사랑이 우리 마음에 부은 바 됨이니
6. 우리가 아직 연약할 때에 기약대로 그리스도께서 경건하지 않은 자를 위하여 죽으셨도다
7. 의인을 위하여 죽는 자가 쉽지 않고 선인을 위하여 용감히 죽는 자가 혹 있거니와
8. 우리가 아직 죄인 되었을 때에 그리스도께서 우리를 위하여 죽으심으로 하나님께서 우리에 대한 자기의 사랑을 확증하셨느니라
9. 그러면 이제 우리가 그의 피로 말미암아 의롭다 하심을 받았으니 더욱 그로 말미암아 진노하심에서 구원을 받을 것이니
10. 곧 우리가 원수 되었을 때에 그의 아들의 죽으심으로 말미암아 하나님과 화목하게 되었은즉 화목하게 된 자로서는 더욱 그의 살아나심으로 말미암아 구원을 받을 것이니라

