7.하나님 찾기(해석)
한사람(아담)의 불순종으로 말미암아 죄가 세상에 들어와 사망이 왕노릇 하게되었다. 하지만 은혜의 하나님은 세상과 사람을 사랑하사 자신의 독생자(예수)를 세상에 보내시어 사망에서 생명으로 가는 길을 열어 주셨다. 한사람의 잘못을 또 한사람의 사랑과 순종함으로 덮음으로 의로움을 가질 은혜의 기회가 생긴것이다. 사람들이 공로없이 받을수 있는 단지 믿음으로 얻을수 있으나 먼저  행하신 예수그리스도의 절대적 희생의 순종하심을 통해서이다.
